# ── настраиваемые глобальные лимиты (v2.1.0) ────────────────────────────────
# 0 означает «без ограничения»: N можно масштабировать до бесконечности.
const MAX_BODIES_REF = Ref{Int}(0)     # потолок числа тел; 0 = ∞
const HAVLOK_REF = Ref{Int}(8)         # порог Хавелока (unphysical-протокол); 0 = выкл.
const BH_THETA_REF = Ref{Float64}(0.6) # угол раскрытия квадродерева Barnes-Hut

"""Perspective projection (OpenGL-style, z in [-1,1])."""
max_bodies() = MAX_BODIES_REF[]
"""bodies: [{position, radius, color, label}]. Returns frame lines."""
set_max_bodies!(n::Int) = (MAX_BODIES_REF[] = max(0, n); MAX_BODIES_REF[])
"""Progress bar in frame: ICE fill on dark track."""
havelok_threshold() = HAVLOK_REF[]
"""Character frame with z-buffer and color."""
set_havelok_threshold!(n::Int) = (HAVLOK_REF[] = max(0, n); HAVLOK_REF[])
"""Vertices and triangles of UV-sphere (poles along y)."""
bh_theta() = BH_THETA_REF[]
"""Radius encoded by symbol density + spot size: r_px < 1 — single"""
set_bh_theta!(t::Real) = (BH_THETA_REF[] = clamp(Float64(t), 1e-6, 10.0);
                         BH_THETA_REF[])

# первичная инициализация из окружения (TRIVORTEX_MAX_BODIES / _HAVLOK / _BH_THETA)
let
    v = tryparse(Int, get(ENV, "TRIVORTEX_MAX_BODIES", ""))
    v !== nothing && set_max_bodies!(v)
    v = tryparse(Int, get(ENV, "TRIVORTEX_HAVLOK", ""))
    v !== nothing && set_havelok_threshold!(v)
    v = tryparse(Float64, get(ENV, "TRIVORTEX_BH_THETA", ""))
    v !== nothing && set_bh_theta!(v)
end

"""symbol density; larger — disk of symbols."""
mutable struct MasterConfig
    G::Float64
    dt::Float64
    n_steps::Int
    n_soften::Float64
    allow_unphysical::Bool
    profile::String
    physics_engine::String
    root::String
    report_formats::Vector{String}
end

const PROFILES = Dict(
    "quick"     => (dt=0.01, steps=100, soften=1e-3, formats=["md", "json"]),
    "standard"  => (dt=0.005, steps=2000, soften=1e-4,
                    formats=["md", "html", "json", "csv"]),
    "precision" => (dt=0.001, steps=5000, soften=1e-6,
                    formats=["txt", "md", "html", "csv", "json", "docx", "pdf"]),
    "demo"      => (dt=0.005, steps=400, soften=1e-4,
                    formats=["txt", "md", "html", "csv", "json", "docx", "pdf", "odt"]),
)

"""trails: list of trails (list[(x,y,z)]) per body — drawn as lines."""
function from_profile(profile::String; n_steps::Union{Int,Nothing}=nothing,
                      allow_unphysical::Bool=false,
                      physics_engine::String="native_newton")
    t = get(PROFILES, profile, PROFILES["standard"])
    MasterConfig(
        G_SI, t.dt,
        n_steps === nothing ? t.steps : n_steps,
        t.soften, allow_unphysical, profile, physics_engine, ROOT,
        String.(t.formats),
    )
end

"""Perspective projection (OpenGL-style, z in [-1,1])."""
resolve_paths(cfg::MasterConfig, root::String=ROOT) =
    (cfg.root = root; cfg)

"""Character frame with z-buffer and color."""
struct UnphysicalConfiguration <: Exception
    msg::String
end

