COLOR_ENABLED = true
COLOR_MODE = "truecolor"

function _is_tty()
    (stdout isa Base.TTY) && (get(ENV, "TERM", "") != "dumb")
end

detect_color_mode!() = begin
    global COLOR_ENABLED, COLOR_MODE
    if get(ENV, "NO_COLOR", "") != "" || get(ENV, "TV_NO_COLOR", "") != ""
        COLOR_ENABLED = false; COLOR_MODE = "none"
    elseif !_is_tty()
        COLOR_MODE = "ansi"          # пайп/файл: минимальный цвет
    elseif get(ENV, "COLORTERM", "") in ("truecolor", "24bit") ||
           occursin("direct", get(ENV, "TERM", "")) ||
           occursin("truecolor", get(ENV, "TERM", ""))
        COLOR_MODE = "truecolor"
    elseif occursin("256color", get(ENV, "TERM", ""))
        COLOR_MODE = "ansi256"
    else
        COLOR_MODE = "truecolor"     # современный терминал по умолчанию
    end
    nothing
end

"""symbol density; larger — disk of symbols."""
function _rgb256(rgb::Tuple{Int,Int,Int})
    r, g, b = rgb
    if abs(r - g) < 9 && abs(g - b) < 9 && abs(r - b) < 9
        r > 238 && return 231
        return clamp(round(Int, (r - 8) / 10), 0, 23) + 232
    end
    16 + 36 * clamp(round(Int, r / 51), 0, 5) +
        6 * clamp(round(Int, g / 51), 0, 5) + clamp(round(Int, b / 51), 0, 5)
end

color_off!() = begin
    global COLOR_ENABLED = false
    nothing
end

"""Progress bar in frame: ICE fill on dark track."""
function colorize(text::String, rgb::Tuple{Int,Int,Int}, bold::Bool=false)
    COLOR_ENABLED || return text
    b = bold ? "1" : "0"
    if COLOR_MODE == "truecolor"
        # v2.2.0: фикс SGR — раньше был пробел перед «m», код ломался
        return "\e[38;2;$(rgb[1]);$(rgb[2]);$(rgb[3]);$(b)m" * text * "\e[0m"
    elseif COLOR_MODE == "ansi256"
        return "\e[38;5;$(_rgb256(rgb));$(b)m" * text * "\e[0m"
    end
    # ANSI 16: приблизим по яркости (последний фолбэк, пайп/файл)
    lum = 0.299 * rgb[1] + 0.587 * rgb[2] + 0.114 * rgb[3]
    code = lum > 180 ? 97 : lum > 110 ? 37 : lum > 50 ? 36 : 34
    s = bold ? "1;" : ""
    return "\e[$s$(code)m" * text * "\e[0m"
end

const SKY = (135, 206, 250)
const ICE = (214, 233, 254)
const GOLD = (232, 199, 102)
const GRN = (52, 211, 153)
const RED = (251, 113, 133)
const ORG = (255, 154, 118)
const GRY = (148, 163, 184)
const CYN = (79, 209, 197)
const YLW = (250, 204, 21)
const WHT = (240, 244, 248)
const VLT = (167, 139, 250)

"""RGB frame with z-buffer."""
print_lines(xs) = (foreach(println, xs); nothing)

"""Character frame with z-buffer and color."""
pad_to(s::String, w::Int) = length(s) >= w ? s : s * repeat(" ", w - length(s))

"""bodies: [{position, radius, color, label}]. Returns frame lines."""
verdict_icon(ok::Bool) = ok ? colorize("✓", GRN, true) : colorize("✗", RED, true)

"""bodies: [{position, radius, color, label}]. Returns frame lines."""
kv(key::String, value; key_w::Int=22) =
    "  " * colorize(pad_to(key, key_w), GRY) * " " * colorize(string(value), WHT)

"""Title bar at top of frame: dark panel + gold text."""
function warn_plate(text::String, width::Int=74)
    edge = colorize("═"^(width - 2), RED, true)
    body = colorize(" ⚠ " * text * " ", RED, true)
    "╔$edge╗\n║$(pad_to(body, width - 2))║\n╚$edge╝"
end

"""Radius encoded by symbol density + spot size: r_px < 1 — single"""
orn(width::Int=74) = "═"^width

