const LANG_REF = Ref{Symbol}(:en)   # интерфейс по умолчанию на английском; --lang ru вернёт русский

set_lang!(l::Symbol)  = (LANG_REF[] = l; l)
get_lang()            = LANG_REF[]
toggle_lang!()        = set_lang!(get_lang() == :ru ? :en : :ru)
lang_label(l::Symbol=get_lang()) = l == :ru ? "РУС" : "EN"

# автодетект из окружения (TRIVORTEX_LANG > LANG); по умолчанию — английский,
# русский включается TRIVORTEX_LANG=ru / LANG=*ru* (или --lang ru в меню)
let
    v = lowercase(get(ENV, "TRIVORTEX_LANG", get(ENV, "LANG", "")))
    if occursin("ru", v)
        set_lang!(:ru)
    end
end

