# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: jsonmini — минимальный JSON (Julia stdlib не имеет JSON)
# Полный RFC 8259: объекты/массивы/строки с \uXXXX/числа/bool/null.
# Сериализатор: escape " \ \n \t, ничего лишнего. Аналог stdlib json Python.
# ═══════════════════════════════════════════════════════════════════════════

module JSONMini

using Printf

export json_parse, json_write

"""Vertices and triangles of UV-sphere (poles along y)."""
mutable struct _Cur
    s::String
    i::Int
end

_skip_ws!(c::_Cur) = begin
    while c.i <= ncodeunits(c.s) && isspace_ws(codeunit(c.s, c.i))
        c.i += 1
    end
end

isspace_ws(b::UInt8) = b == 0x20 || b == 0x09 || b == 0x0A || b == 0x0D

"""bodies: [{position, radius, color, label}]. Returns frame lines."""
function _value!(c::_Cur)
    _skip_ws!(c)
    c.i > ncodeunits(c.s) && error("JSON: неожиданный конец")
    ch = codeunit(c.s, c.i)
    if ch == UInt8('{')
        return _object!(c)
    elseif ch == UInt8('[')
        return _array!(c)
    elseif ch == UInt8('"')
        return _string!(c)
    elseif ch == UInt8('t')
        _expect!(c, "true"); return true
    elseif ch == UInt8('f')
        _expect!(c, "false"); return false
    elseif ch == UInt8('n')
        _expect!(c, "null"); return nothing
    else
        return _number!(c)
    end
end

function _expect!(c::_Cur, word::String)
    for ch in word
        c.i > ncodeunits(c.s) && error("JSON: ожидалось $word")
        codeunit(c.s, c.i) == UInt8(ch) || error("JSON: ожидалось $word")
        c.i += 1
    end
end

function _object!(c::_Cur)
    d = Dict{String,Any}()
    c.i += 1  # {
    _skip_ws!(c)
    if c.i <= ncodeunits(c.s) && codeunit(c.s, c.i) == UInt8('}')
        c.i += 1
        return d
    end
    while true
        _skip_ws!(c)
        k = _string!(c)
        _skip_ws!(c)
        c.i > ncodeunits(c.s) && error("JSON: ожидался ':'")
        codeunit(c.s, c.i) == UInt8(':') || error("JSON: ожидался ':'")
        c.i += 1
        d[k] = _value!(c)
        _skip_ws!(c)
        c.i > ncodeunits(c.s) && error("JSON: незакрытый объект")
        ch = codeunit(c.s, c.i)
        if ch == UInt8(',')
            c.i += 1
        elseif ch == UInt8('}')
            c.i += 1
            return d
        else
            error("JSON: ожидались ',' или '}'")
        end
    end
end

function _array!(c::_Cur)
    a = Vector{Any}()
    c.i += 1  # [
    _skip_ws!(c)
    if c.i <= ncodeunits(c.s) && codeunit(c.s, c.i) == UInt8(']')
        c.i += 1
        return a
    end
    while true
        push!(a, _value!(c))
        _skip_ws!(c)
        c.i > ncodeunits(c.s) && error("JSON: незакрытый массив")
        ch = codeunit(c.s, c.i)
        if ch == UInt8(',')
            c.i += 1
        elseif ch == UInt8(']')
            c.i += 1
            return a
        else
            error("JSON: ожидались ',' или ']'")
        end
    end
end

function _string!(c::_Cur)
    c.i += 1  # "
    buf = IOBuffer()
    while c.i <= ncodeunits(c.s)
        b = codeunit(c.s, c.i)
        if b == UInt8('"')
            c.i += 1
            return String(take!(buf))
        elseif b == UInt8('\\')
            c.i += 1
            c.i > ncodeunits(c.s) && error("JSON: обрыв эскейпа")
            e = codeunit(c.s, c.i)
            if e == UInt8('"');  write(buf, '"')
            elseif e == UInt8('\\'); write(buf, '\\')
            elseif e == UInt8('/');  write(buf, '/')
            elseif e == UInt8('b');  write(buf, '\b')
            elseif e == UInt8('f');  write(buf, '\f')
            elseif e == UInt8('n');  write(buf, '\n')
            elseif e == UInt8('r');  write(buf, '\r')
            elseif e == UInt8('t');  write(buf, '\t')
            elseif e == UInt8('u')
                hex = SubString(c.s, c.i + 1, c.i + 4)
                cp = parse(UInt32, hex; base=16)
                c.i += 4
                # суррогатная пара
                if 0xD800 <= cp <= 0xDBFF && c.i + 6 <= ncodeunits(c.s) &&
                   codeunit(c.s, c.i + 1) == UInt8('\\') &&
                   codeunit(c.s, c.i + 2) == UInt8('u')
                    lo = parse(UInt32, SubString(c.s, c.i + 3, c.i + 6); base=16)
                    if 0xDC00 <= lo <= 0xDFFF
                        cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00)
                        c.i += 6
                    end
                end
                write(buf, Char(cp))
            else
                error("JSON: неизвестный эскейп \\$e")
            end
            c.i += 1
        else
            write(buf, b)
            c.i += 1
        end
    end
    error("JSON: незакрытая строка")
end

function _number!(c::_Cur)
    start = c.i
    c.i <= ncodeunits(c.s) && (codeunit(c.s, c.i) == UInt8('-')) && (c.i += 1)
    isint = true
    while c.i <= ncodeunits(c.s)
        b = codeunit(c.s, c.i)
        if b == UInt8('.') || b == UInt8('e') || b == UInt8('E')
            isint = false
            c.i += 1
        elseif (UInt8('0') <= b <= UInt8('9')) || b == UInt8('+') || b == UInt8('-')
            c.i += 1
        else
            break
        end
    end
    sub = SubString(c.s, start, c.i - 1)
    isint ? (tryparse(Int64, sub) !== nothing ? tryparse(Int64, sub) : tryparse(Float64, sub)) :
        tryparse(Float64, sub)
end

"""json_parse(str) -> Any (Dict/Vector/String/Float64/Int64/Bool/Nothing)."""
function json_parse(s::String)
    c = _Cur(s, 1)
    v = _value!(c)
    _skip_ws!(c)
    v
end

"""Vertices and triangles of UV-sphere (poles along y)."""
function _esc(s::String)
    buf = IOBuffer()
    for ch in s
        if ch == '"';    write(buf, "\\\"")
        elseif ch == '\\'; write(buf, "\\\\")
        elseif ch == '\n'; write(buf, "\\n")
        elseif ch == '\r'; write(buf, "\\r")
        elseif ch == '\t'; write(buf, "\\t")
        elseif ch < ' '
            @printf(buf, "\\u%04x", UInt16(ch))
        else
            write(buf, ch)
        end
    end
    String(take!(buf))
end

_write!(buf::IOBuffer, x::Nothing) = write(buf, "null")
_write!(buf::IOBuffer, x::Bool) = write(buf, x ? "true" : "false")
_write!(buf::IOBuffer, x::Integer) = @printf(buf, "%d", x)
function _write!(buf::IOBuffer, x::AbstractFloat)
    isfinite(x) || (write(buf, "null"); return)
    @printf(buf, "%.17g", x)
end
_write!(buf::IOBuffer, x::AbstractString) = write(buf, "\"", _esc(String(x)), "\"")
function _write!(buf::IOBuffer, x::Union{Dict,AbstractDict})
    write(buf, '{')
    first = true
    for (k, v) in x
        first || write(buf, ',')
        first = false
        _write!(buf, String(k))
        write(buf, ':')
        _write!(buf, v)
    end
    write(buf, '}')
end
function _write!(buf::IOBuffer, x::Union{AbstractVector,Tuple})
    write(buf, '[')
    first = true
    for v in x
        first || write(buf, ',')
        first = false
        _write!(buf, v)
    end
    write(buf, ']')
end
function _write!(buf::IOBuffer, x::Union{NamedTuple, Pair})
    error("json_write: неподдерживаемый тип $(typeof(x))")
end

"""json_write(obj) -> String."""
function json_write(x)
    buf = IOBuffer()
    _write!(buf, x)
    String(take!(buf))
end

end # module JSONMini

using .JSONMini: json_parse, json_write

