# БЛОК: data materialization — аналог _EMBEDDED_DATA Python (gzip+base64)
# Те же data-файлы, что в Python-издании; парсятся при старте JSONMini.
# ═══════════════════════════════════════════════════════════════════════════

# (data_literals.jl вставляется сборщиком сюда — 6 raw-констант TV_EMBEDDED_*)

"""Progress bar in frame: ICE fill on dark track."""
function json_parse_wrap_ok(s::String)
    try
        return json_parse(s)
    catch e
        @warn "embedded JSON parse failed" exception = e
        return nothing
    end
end

const TV_CATALOG_JSON = json_parse_wrap_ok(TV_EMBEDDED_CATALOG)
const TV_PRESETS_JSON = json_parse_wrap_ok(TV_EMBEDDED_PRESETS)
const TV_TRAJECTORIES_JSON = json_parse_wrap_ok(TV_EMBEDDED_TRAJECTORIES)
const TV_EXOPLANETS_JSON = TV_EMBEDDED_EXOPLANETS  # ленивый разбор (1.5 МБ)
const TV_LITERATURE_MD = TV_EMBEDDED_LITERATURE
const TV_README_MD = TV_EMBEDDED_README

"""symbol density; larger — disk of symbols."""
function load_exoplanets_cache()
    d = json_parse_wrap_ok(TV_EXOPLANETS_JSON)
    d === nothing && return Dict{String,Any}()
    return d
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: lab/body.py — тело с циркуляцией (вихри) и валидацией
# ═══════════════════════════════════════════════════════════════════════════

mutable struct Body
    id::String
    name::String
    mass::Float64
    radius::Float64
    position::Vector{Float64}
    velocity::Vector{Float64}
    color::String
    type::String
    source::String
    circulation::Float64
end

Body(id, name, mass, radius, pos, vel; color="#4FD1C5", type="body",
     source="synthetic", circulation=0.0) =
    Body(id, name, mass, radius, pos, vel, color, type, source, circulation)

"""Radius encoded by symbol density + spot size: r_px < 1 — single"""
function validate_body(b::Body)
    problems = String[]
    b.mass <= 0 && push!(problems, "масса ≤ 0")
    b.radius <= 0 && push!(problems, "радиус ≤ 0")
    (all(isfinite.(b.position)) && all(isfinite.(b.velocity))) ||
        push!(problems, "нефинитное состояние")
    problems
end

kinetic(b::Body) = 0.5 * b.mass * dot(b.velocity, b.velocity)

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: lab/scene.py — сцена: тела, история, события, unphysical-протокол
# ═══════════════════════════════════════════════════════════════════════════

mutable struct Scene
    name::String
    config::MasterConfig
    bodies::Vector{Body}
    t::Float64
    dt::Float64
    unphysical_flag::Bool
    events::Vector{String}
    trajectory_history::Vector{Any}   # кадры: t + плоские координаты
    engine_name::String
    metadata::Dict{String,Any}
end

function Scene(config::MasterConfig; name::String="")
    Scene(name, config, Body[], 0.0, config.dt, false, String[],
          Any[], config.physics_engine, Dict{String,Any}())
end

n_bodies(sc::Scene) = length(sc.bodies)

"""RGB frame with z-buffer.

Radius encoded by symbol density + spot size: r_px < 1 — single
symbol density; larger — disk of symbols.
Radius encoded by symbol density + spot size: r_px < 1 — single
  Character frame with z-buffer and color.
  Title bar at top of frame: dark panel + gold text."""
function add_body!(sc::Scene, b::Body)
    n = n_bodies(sc)
    new_n = n + 1
    cap = max_bodies()
    hav = havelok_threshold()
    if cap > 0 && new_n > cap
        throw(UnphysicalConfiguration(
            "N=$new_n > max_bodies=$cap: настраиваемый потолок " *
            "(--max-bodies / меню «Настройки», 0 = без ограничения)"))
    elseif hav > 0 && new_n >= hav && !sc.config.allow_unphysical &&
           !sc.unphysical_flag
        throw(UnphysicalConfiguration(
            "N=$new_n ≥ $hav: порог Хавелока; " *
            "разрешите флагом --allow-unphysical (или --havelok 0)"))
    end
    push!(sc.bodies, b)
    if hav > 0 && n_bodies(sc) >= hav
        sc.unphysical_flag = true
        push!(sc.events,
              "unphysical N=$(n_bodies(sc)): конфигурация за порогом Хавелока")
    end
    b
end

"""Perspective projection (OpenGL-style, z in [-1,1])."""
function validate(sc::Scene)
    problems = String[]
    n = n_bodies(sc)
    cap = max_bodies()
    hav = havelok_threshold()
    if n < 2
        push!(problems, "N=$n < 2: задача одного тела тривиальна")
    elseif hav > 0 && n >= hav && !sc.unphysical_flag
        push!(problems, "N=$n ≥ $hav: вне теоремы Хавелока")
    end
    if cap > 0 && n > cap
        push!(problems, "N=$n > max_bodies=$cap: потолок числа тел")
    end
    for b in sc.bodies, p in validate_body(b)
        push!(problems, "$(b.id): $p")
    end
    # мгновенные столкновения (validator-логика: перекрытие радиусов)
    for i in 1:n, j in i+1:n
        d = norm(sc.bodies[i].position - sc.bodies[j].position)
        if d < sc.bodies[i].radius + sc.bodies[j].radius
            push!(problems, "столкновение $(sc.bodies[i].id)-$(sc.bodies[j].id)")
        end
    end
    (ok=isempty(problems), problems=problems)
end

"""Radius encoded by symbol density + spot size: r_px < 1 — single"""
function total_energy(sc::Scene)
    ke = sum(kinetic.(sc.bodies))
    pe = 0.0
    n = n_bodies(sc)
    for i in 1:n, j in i+1:n
        r = norm(sc.bodies[i].position - sc.bodies[j].position)
        r > 0 && (pe -= sc.config.G * sc.bodies[i].mass * sc.bodies[j].mass / r)
    end
    ke + pe
end

"""bodies: [{position, radius, color, label}]. Returns frame lines."""
function observables(sc::Scene)
    P = sum(b.mass .* b.velocity for b in sc.bodies)
    L = reduce(+, (b.mass .* cross(b.position, b.velocity) for b in sc.bodies);
               init=zeros(3))
    (energy=total_energy(sc), momentum=P, angular=L)
end

"""RGB frame with z-buffer."""
function scene_to_dict(sc::Scene; include_history::Bool=false)
    d = Dict{String,Any}(
        "name" => sc.name,
        "t" => sc.t,
        "dt" => sc.dt,
        "engine" => sc.engine_name,
        "unphysical_flag" => sc.unphysical_flag,
        "events" => sc.events,
        "bodies" => [
            Dict("id" => b.id, "name" => b.name, "mass" => b.mass,
                 "radius" => b.radius,
                 "position" => [round(c, digits=15) for c in b.position],
                 "velocity" => [round(c, digits=15) for c in b.velocity],
                 "color" => b.color, "type" => b.type, "source" => b.source)
            for b in sc.bodies
        ],
    )
    if include_history
        d["trajectory_history"] = sc.trajectory_history
    end
    d
end

"""RGB frame with z-buffer."""
function scene_save(sc::Scene, path::String; include_history::Bool=true)
    open(path, "w") do fh
        write(fh, json_write(scene_to_dict(sc; include_history=include_history)))
    end
    path
end

"""Perspective projection (OpenGL-style, z in [-1,1])."""
function scene_load(path::String, config::MasterConfig)
    d = json_parse(read(path, String))
    sc = Scene(config; name=String(d["name"]))
    sc.t = Float64(d["t"])
    sc.dt = Float64(d["dt"])
    sc.engine_name = String(get(d, "engine", "native_newton"))
    sc.unphysical_flag = Bool(get(d, "unphysical_flag", false))
    for e in get(d, "events", [])
        push!(sc.events, String(e))
    end
    for bd in d["bodies"]
        add_body!(sc, Body(
            String(bd["id"]), String(bd["name"]), Float64(bd["mass"]),
            Float64(bd["radius"]),
            [Float64(x) for x in bd["position"]],
            [Float64(x) for x in bd["velocity"]],
            color=String(get(bd, "color", "#4FD1C5")),
            type=String(get(bd, "type", "body")),
            source=String(get(bd, "source", "synthetic"))))
    end
    hist = get(d, "trajectory_history", [])
    sc.trajectory_history = collect(hist)
    sc
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: lab/units.py — системы единиц: СИ / астрономическая / модельная
# ═══════════════════════════════════════════════════════════════════════════

"""Character frame with z-buffer and color."""
module UnitsL
export ms_to_au, au_to_m, kg_to_msun, msun_to_kg, kms_to_aud

au_to_m(x) = x * 1.495978707e11
ms_to_au(x) = x / 1.495978707e11
kg_to_msun(x) = x / 1.9884e30
msun_to_kg(x) = x * 1.9884e30
kms_to_aud(x) = x * 1000 * 365.25 * 86400 / 1.495978707e11
aud_to_kms(x) = x * 1.495978707e11 / (365.25 * 86400) / 1000

end # UnitsL

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: lab/integrators.py — RK4 / leapfrog (KDK) / Yoshida-4
# ═══════════════════════════════════════════════════════════════════════════

"""Title bar at top of frame: dark panel + gold text."""
function newton_accelerations(bodies::Vector{Body}, G::Float64, soften::Float64)
    n = length(bodies)
    acc = [zeros(3) for _ in 1:n]
    for i in 1:n, j in i+1:n
        dx = bodies[j].position - bodies[i].position
        r2 = dot(dx, dx) + soften * soften
        inv_r3 = 1.0 / (r2 * sqrt(r2))
        f = G * inv_r3
        acc[i] .+= f * bodies[j].mass .* dx
        acc[j] .-= f * bodies[i].mass .* dx
    end
    acc
end

"""trails: list of trails (list[(x,y,z)]) per body — drawn as lines."""
function rk4_step!(sc::Scene)
    G, soft, dt = sc.config.G, sc.config.n_soften, sc.dt
    n = n_bodies(sc)
    ps = [copy(b.position) for b in sc.bodies]
    vs = [copy(b.velocity) for b in sc.bodies]
    acc(p) = newton_accelerations([Body("t", "t", sc.bodies[i].mass, 1.0, p[i], vs[i])
                                   for i in 1:n], G, soft)

    k1v = acc(ps)
    k1p = [copy(vs[i]) for i in 1:n]
    ps2 = [ps[i] .+ 0.5 .* dt .* k1p[i] for i in 1:n]
    k2v = acc(ps2)
    ps3 = [ps[i] .+ 0.5 .* dt .* k1p[i] .+ 0.25 .* dt^2 .* k1v[i] for i in 1:n]
    k3v = acc(ps3)
    ps4 = [ps[i] .+ dt .* k1p[i] .+ 0.5 .* dt^2 .* k2v[i] for i in 1:n]
    k4v = acc(ps4)

    for i in 1:n
        sc.bodies[i].position .= ps[i] .+ dt .* k1p[i] .+
                                 dt^2 / 6 .* (k1v[i] .+ k2v[i] .+ k3v[i])
        sc.bodies[i].velocity .= vs[i] .+
            dt / 6 .* (k1v[i] .+ 2 .* k2v[i] .+ 2 .* k3v[i] .+ k4v[i])
    end
    sc.t += dt
end

"""Title bar at top of frame: dark panel + gold text."""
function leapfrog_step!(sc::Scene)
    G, soft, dt = sc.config.G, sc.config.n_soften, sc.dt
    acc = newton_accelerations(sc.bodies, G, soft)
    for i in eachindex(sc.bodies)
        sc.bodies[i].velocity .+= 0.5 .* dt .* acc[i]
    end
    for b in sc.bodies
        b.position .+= dt .* b.velocity
    end
    acc = newton_accelerations(sc.bodies, G, soft)
    for i in eachindex(sc.bodies)
        sc.bodies[i].velocity .+= 0.5 .* dt .* acc[i]
    end
    sc.t += dt
end

"""symbol density; larger — disk of symbols.
kick(w1/2) drift(w1) kick((w1+w0)/2) drift(w0) kick((w1+w0)/2) drift(w1) kick(w1/2)"""
function yoshida4_step!(sc::Scene)
    # Yoshida 1990: w1 = 1/(2−2^(1/3)), w0 = −2^(1/3)·w1
    cbrt2 = 2.0^(1.0 / 3.0)
    w1 = 1.0 / (2.0 - cbrt2)
    w0 = -cbrt2 * w1
    G, soft = sc.config.G, sc.config.n_soften
    dt = sc.dt
    cmid = (w1 + w0) / 2.0
    for (c, d) in ((w1 / 2, w1), (cmid, w0), (cmid, w1))
        acc = newton_accelerations(sc.bodies, G, soft)
        for i in eachindex(sc.bodies)
            sc.bodies[i].velocity .+= c .* dt .* acc[i]
        end
        for b in sc.bodies
            b.position .+= d .* dt .* b.velocity
        end
    end
    acc = newton_accelerations(sc.bodies, G, soft)
    for i in eachindex(sc.bodies)
        sc.bodies[i].velocity .+= (w1 / 2) .* dt .* acc[i]
    end
    sc.t += dt
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: lab/physics.py — движки: native_newton / native_vortex / Barnes-Hut
# ═══════════════════════════════════════════════════════════════════════════

"""bodies: [{position, radius, color, label}]. Returns frame lines."""
function vortex_velocities(bodies, circulations)
    n = length(bodies)
    out = Vector{Vector{Float64}}(undef, n)
    for i in 1:n
        vx = 0.0; vy = 0.0
        for j in 1:n
            i == j && continue
            dx = bodies[j].position[1] - bodies[i].position[1]
            dy = bodies[j].position[2] - bodies[i].position[2]
            r2 = dx * dx + dy * dy
            r2 <= 0 && continue
            vx += -circulations[j] * dy / (2 * pi * r2)
            vy += circulations[j] * dx / (2 * pi * r2)
        end
        out[i] = [vx, vy]
    end
    out
end

"""Progress bar in frame: ICE fill on dark track."""
function kirchhoff_hamiltonian(bodies, circulations)
    H = 0.0
    n = length(bodies)
    for i in 1:n, j in 1:n
        i == j && continue
        dx = bodies[i].position[1] - bodies[j].position[1]
        dy = bodies[i].position[2] - bodies[j].position[2]
        r2 = dx * dx + dy * dy
        r2 > 0 && (H -= (circulations[i] * circulations[j] / (4 * pi)) * 0.5 * log(r2))
    end
    H
end

"""Progress bar in frame: ICE fill on dark track."""
function kirchhoff_integrals(bodies, circulations)
    P = sum(circulations[i] * bodies[i].position[1] for i in eachindex(bodies))
    Q = sum(circulations[i] * bodies[i].position[2] for i in eachindex(bodies))
    I = sum(circulations[i] * (bodies[i].position[1]^2 + bodies[i].position[2]^2)
            for i in eachindex(bodies))
    (H=kirchhoff_hamiltonian(bodies, circulations), P=P, Q=Q, I=I)
end

"""Progress bar in frame: ICE fill on dark track."""
function vortex_step!(sc::Scene, circulations)
    bodies = sc.bodies
    n = length(bodies)
    function deriv(y)
        saved = [(b.position[1], b.position[2]) for b in bodies]
        for i in 1:n
            bodies[i].position[1] = y[2i-1]
            bodies[i].position[2] = y[2i]
        end
        vel = vortex_velocities(bodies, circulations)
        for i in 1:n
            bodies[i].position[1] = saved[i][1]
            bodies[i].position[2] = saved[i][2]
        end
        out = Float64[]
        for i in 1:n
            if abs(circulations[i]) < 1e-15
                append!(out, (0.0, 0.0))  # невихревое тело неподвижно
            else
                append!(out, (vel[i][1], vel[i][2]))
            end
        end
        out
    end
    y0 = Float64[]
    for b in bodies
        append!(y0, (b.position[1], b.position[2]))
    end
    dt = sc.dt
    k1 = deriv(y0)
    k2 = deriv(y0 .+ dt / 2 .* k1)
    k3 = deriv(y0 .+ dt / 2 .* k2)
    k4 = deriv(y0 .+ dt .* k3)
    y1 = y0 .+ dt / 6 .* (k1 .+ 2 .* k2 .+ 2 .* k3 .+ k4)
    for i in 1:n
        bodies[i].position[1] = y1[2i-1]
        bodies[i].position[2] = y1[2i]
        bodies[i].velocity .= 0.0
    end
    sc.t += dt
end

"""symbol density; larger — disk of symbols.
bodies: [{position, radius, color, label}]. Returns frame lines."""
function integral_drifts(sc::Scene, circulations=Float64[])
    isempty(sc.trajectory_history) && return Dict{String,Any}("error" => "у сцены нет истории")
    if occursin("vortex", sc.engine_name)
        Hs = Float64[]; Ps = Float64[]; Qs = Float64[]; Is = Float64[]
        ref = [Body("i$i", "i", 1.0, 1.0, zeros(3), zeros(3)) for i in eachindex(circulations)]
        for state in sc.trajectory_history
            flat = state[2:end]
            for i in eachindex(ref)
                ref[i].position[1] = flat[3*i-2]
                ref[i].position[2] = flat[3*i-1]
            end
            ints = kirchhoff_integrals(ref, circulations)
            push!(Hs, ints.H); push!(Ps, ints.P); push!(Qs, ints.Q); push!(Is, ints.I)
        end
        rel(v) = isempty(v) ? 0.0 : abs(v[end] - v[1]) / max(abs(v[1]), 1e-12)
        return Dict{String,Any}(
            "engine" => sc.engine_name,
            "H_drift" => rel(Hs), "P_drift" => abs(Ps[end] - Ps[1]),
            "Q_drift" => abs(Qs[end] - Qs[1]), "I_drift" => rel(Is),
            "H0" => Hs[1], "ladder_criterion" => "V3/V4: дрейф ≤ 1e-10",
            "passed" => rel(Hs) <= 1e-10 && rel(Is) <= 1e-10 &&
                        abs(Ps[end] - Ps[1]) <= 1e-10 && abs(Qs[end] - Qs[1]) <= 1e-10)
    else
        Es = Float64[]; Ps = Float64[]; Ls = Float64[]
        for state in sc.trajectory_history
            flat = state[2:end]
            n = length(flat) ÷ 6
            ke = pe = 0.0; px = py = pz = 0.0; lx = ly = lz = 0.0
            masses = [b.mass for b in sc.bodies]
            for i in 1:n
                x = flat[3*i-2]; y = flat[3*i-1]; z = flat[3*i]
                vx = flat[3*n+3*i-2]; vy = flat[3*n+3*i-1]; vz = flat[3*n+3*i]
                ke += 0.5 * masses[i] * (vx^2 + vy^2 + vz^2)
                px += masses[i] * vx; py += masses[i] * vy; pz += masses[i] * vz
                lx += masses[i] * (y * vz - z * vy)
                ly += masses[i] * (z * vx - x * vz)
                lz += masses[i] * (x * vy - y * vx)
            end
            for i in 1:n, j in i+1:n
                dx = flat[3*j-2] - flat[3*i-2]; dy = flat[3*j-1] - flat[3*i-1]
                dz = flat[3*j] - flat[3*i]
                r = sqrt(dx^2 + dy^2 + dz^2)
                r > 0 && (pe -= sc.config.G * masses[i] * masses[j] / r)
            end
            push!(Es, ke + pe)
            push!(Ps, hypot(px, py, pz))
            push!(Ls, hypot(lx, ly, lz))
        end
        reldrift(v) = abs(v[end] - v[1]) / max(abs(v[1]), 1e-12)
        return Dict{String,Any}(
            "engine" => sc.engine_name,
            "H_drift" => reldrift(Es), "P_drift" => reldrift(Ps), "Q_drift" => 0.0,
            "I_drift" => reldrift(Ls),
            "passed" => reldrift(Es) <= 1e-10 && reldrift(Ps) <= 1e-10 &&
                        reldrift(Ls) <= 1e-10)
    end
end

"""Title bar at top of frame: dark panel + gold text."""
available_engines() = ["native_newton", "native_vortex", "barnes_hut"]

"""Title bar at top of frame: dark panel + gold text."""
function get_engine(sc::Scene, name::String)
    name in available_engines() || name == "native_newton" || begin
        push!(sc.events, "fallback движок: $name недоступен → native_newton")
        return "native_newton"
    end
    if name in ("rebound", "dedalus")
        push!(sc.events, "fallback: адаптер $name не установлен → native (штатный)")
        return "native_newton"
    end
    name
end

"""Character frame with z-buffer and color.
Vertices and triangles of UV-sphere (poles along y)."""
function barnes_hut_step!(sc::Scene; theta::Union{Float64,Nothing}=nothing)
    θ = theta === nothing ? bh_theta() : theta
    bodies = [SimBody(b.position[1], b.position[2], b.position[3], b.mass,
                      b.velocity[1], b.velocity[2], b.velocity[3], i)
              for (i, b) in enumerate(sc.bodies)]
    bh_step_all!(bodies, sc.dt, sc.config.G, θ, sc.config.n_soften)
    for (i, b) in enumerate(bodies)
        sc.bodies[i].position .= (b.x, b.y, b.z)
        sc.bodies[i].velocity .= (b.vx, b.vy, b.vz)
    end
    sc.t += sc.dt
    sc
end

"""trails: list of trails (list[(x,y,z)]) per body — drawn as lines.

v2.1.0:
bodies: [{position, radius, color, label}]. Returns frame lines.
  symbol density; larger — disk of symbols.
Character frame with z-buffer and color.
  symbol density; larger — disk of symbols."""
function run_simulation!(sc::Scene; n_steps::Union{Int,Nothing}=nothing,
                         engine::Union{String,Nothing}=nothing,
                         circulations::Vector{Float64}=Float64[],
                         history_every::Int=1,
                         progress::Union{Bool,Nothing}=nothing)
    n = n_steps === nothing ? sc.config.n_steps : n_steps
    hev = max(1, history_every)
    eng = get_engine(sc, engine === nothing ? sc.config.physics_engine : engine)
    sc.engine_name = eng
    hist = Any[]
    push_frame!() = push!(hist, vcat(sc.t,
        [c for b in sc.bodies for c in b.position],
        [c for b in sc.bodies for c in b.velocity]))
    push_frame!()
    # v2.2.0: прогресс-бар (авто: TTY и достаточно долгий прогон)
    show_pb = progress === nothing ? (stdout isa Base.TTY && n >= 500) : progress
    pb = show_pb ? ProgressBar(n; width=34, label=eng) : nothing
    if eng == "native_vortex"
        circ = isempty(circulations) ? [b.circulation for b in sc.bodies] : circulations
        for s in 1:n
            vortex_step!(sc, circ)
            pb === nothing || track!(pb)
            (s % hev == 0 || s == n) && push_frame!()
        end
    elseif eng == "barnes_hut"
        # быстрый путь: конвертация один раз, шаги в SimBody-пространстве
        bodies = [SimBody(b.position[1], b.position[2], b.position[3], b.mass,
                          b.velocity[1], b.velocity[2], b.velocity[3], i)
                  for (i, b) in enumerate(sc.bodies)]
        θ = bh_theta()
        for s in 1:n
            bh_step_all!(bodies, sc.dt, sc.config.G, θ, sc.config.n_soften)
            pb === nothing || track!(pb)
            sc.t += sc.dt
            if s % hev == 0 || s == n
                for (i, b) in enumerate(bodies)
                    sc.bodies[i].position .= (b.x, b.y, b.z)
                    sc.bodies[i].velocity .= (b.vx, b.vy, b.vz)
                end
                push_frame!()
            end
        end
    else
        for s in 1:n
            rk4_step!(sc)
            pb === nothing || track!(pb)
            (s % hev == 0 || s == n) && push_frame!()
        end
    end
    sc.trajectory_history = hist
    if pb !== nothing
        finish!(pb; suffix="  " * colorize(
            "✓ " * @sprintf("%d %s", n, tr("pb.steps")), TL_GREEN, true))
    end
    sc
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: lab/nbody_tree.py — квадродерево Barnes-Hut + benchmark
# ═══════════════════════════════════════════════════════════════════════════

mutable struct SimBody
    x::Float64; y::Float64; z::Float64
    mass::Float64
    vx::Float64; vy::Float64; vz::Float64
    id::Int
end

mutable struct QuadNode
    cx::Float64; cy::Float64; half::Float64
    mass::Float64
    com_x::Float64; com_y::Float64
    children::Vector{QuadNode}
    bodies_idx::Vector{Int}
    is_leaf::Bool
end

_make_node(cx, cy, half) = QuadNode(cx, cy, half, 0.0, 0.0, 0.0, QuadNode[], Int[], true)

function _subdivide!(node::QuadNode)
    h = node.half / 2
    node.children = [_make_node(node.cx - h, node.cy - h, h),
                     _make_node(node.cx + h, node.cy - h, h),
                     _make_node(node.cx - h, node.cy + h, h),
                     _make_node(node.cx + h, node.cy + h, h)]
    node.is_leaf = false
end

_which_child(node::QuadNode, b::SimBody) =
    1 + ((b.x > node.cx) ? 1 : 0) + ((b.y > node.cy) ? 2 : 0)

function _insert_balanced!(node::QuadNode, bodies::Vector{SimBody}, i::Int)
    b = bodies[i]
    if node.is_leaf
        if isempty(node.bodies_idx)
            push!(node.bodies_idx, i)
            return
        end
        old = node.bodies_idx[1]
        _subdivide!(node)
        empty!(node.bodies_idx)
        _insert_balanced!(node.children[_which_child(node, bodies[old])], bodies, old)
        _insert_balanced!(node.children[_which_child(node, b)], bodies, i)
        return
    end
    _insert_balanced!(node.children[_which_child(node, b)], bodies, i)
end

function _summarize!(node::QuadNode, bodies::Vector{SimBody})
    if node.is_leaf
        m = 0.0; cx = 0.0; cy = 0.0
        for i in node.bodies_idx
            m += bodies[i].mass
            cx += bodies[i].mass * bodies[i].x
            cy += bodies[i].mass * bodies[i].y
        end
        if m > 0
            node.mass = m; node.com_x = cx / m; node.com_y = cy / m
        end
        return node
    end
    m = 0.0; cx = 0.0; cy = 0.0
    for ch in node.children
        _summarize!(ch, bodies)
        m += ch.mass; cx += ch.mass * ch.com_x; cy += ch.mass * ch.com_y
    end
    if m > 0
        node.mass = m; node.com_x = cx / m; node.com_y = cy / m
    end
    node
end

function build_tree(bodies::Vector{SimBody})
    xs = [b.x for b in bodies]; ys = [b.y for b in bodies]
    cx = (maximum(xs) + minimum(xs)) / 2
    cy = (maximum(ys) + minimum(ys)) / 2
    half = max(maximum(xs) - minimum(xs), maximum(ys) - minimum(ys)) / 2 + 1e-6
    root = _make_node(cx, cy, half)
    for i in eachindex(bodies)
        _insert_balanced!(root, bodies, i)
    end
    _summarize!(root, bodies)
    root
end

"""bodies: [{position, radius, color, label}]. Returns frame lines."""
function tree_force(node::QuadNode, bodies::Vector{SimBody}, i::Int,
                    theta::Float64, soften::Float64, G::Float64)
    b = bodies[i]
    dx = node.com_x - b.x; dy = node.com_y - b.y
    r2 = dx * dx + dy * dy + soften * soften
    r = sqrt(r2)
    if node.is_leaf
        fx = 0.0; fy = 0.0
        for j in node.bodies_idx
            j == i && continue
            ddx = bodies[j].x - b.x; ddy = bodies[j].y - b.y
            rr2 = ddx * ddx + ddy * ddy + soften * soften
            rr = sqrt(rr2)
            f = G * bodies[j].mass / (rr2 * rr)
            fx += f * ddx; fy += f * ddy
        end
        return (fx, fy)
    end
    if node.half * 2 / r < theta
        f = G * node.mass / (r2 * r)
        return (f * dx, f * dy)
    end
    fx = 0.0; fy = 0.0
    for ch in node.children
        ch.mass > 0 || continue
        (ax, ay) = tree_force(ch, bodies, i, theta, soften, G)
        fx += ax; fy += ay
    end
    (fx, fy)
end

"""Progress bar in frame: ICE fill on dark track."""
function bh_step_all!(bodies::Vector{SimBody}, dt, G, theta, soften)
    tree = build_tree(bodies)
    for i in eachindex(bodies)
        (fx, fy) = tree_force(tree, bodies, i, theta, soften, G)
        bodies[i].vx += 0.5 * dt * fx
        bodies[i].vy += 0.5 * dt * fy
    end
    for b in bodies
        b.x += dt * b.vx; b.y += dt * b.vy
    end
    tree = build_tree(bodies)
    for i in eachindex(bodies)
        (fx, fy) = tree_force(tree, bodies, i, theta, soften, G)
        bodies[i].vx += 0.5 * dt * fx
        bodies[i].vy += 0.5 * dt * fy
    end
end

"""Progress bar in frame: ICE fill on dark track."""
function direct_forces(bodies::Vector{SimBody}, G, soften)
    n = length(bodies)
    out = Vector{Tuple{Float64,Float64}}(undef, n)
    for i in 1:n
        fx = 0.0; fy = 0.0
        for j in 1:n
            i == j && continue
            dx = bodies[j].x - bodies[i].x; dy = bodies[j].y - bodies[i].y
            r2 = dx^2 + dy^2 + soften^2
            inv_r = 1 / sqrt(r2)
            fx += G * bodies[j].mass * inv_r / r2 * dx
            fy += G * bodies[j].mass * inv_r / r2 * dy
        end
        out[i] = (fx, fy)
    end
    out
end

"""RGB frame with z-buffer."""
function bh_self_check()
    rng = MersenneTwister(7)
    n = 120
    bodies = [SimBody(0.0, 0.0, 0.0, 1 / n, 0.0, 0.0, 0.0, i) for i in 1:n]
    for b in bodies
        b.x = rand(rng) * 2 - 1; b.y = rand(rng) * 2 - 1; b.z = rand(rng) * 0.2 - 0.1
        b.vx = rand(rng) * 0.4 - 0.2; b.vy = rand(rng) * 0.4 - 0.2
    end
    function energy(bs)
        ke = sum(0.5 * b.mass * (b.vx^2 + b.vy^2) for b in bs)
        pe = 0.0
        for i in eachindex(bs), j in i+1:length(bs)
            d = sqrt((bs[i].x - bs[j].x)^2 + (bs[i].y - bs[j].y)^2 + 0.02^2)
            pe -= bs[i].mass * bs[j].mass / d
        end
        ke + pe
    end
    e0 = energy(bodies)
    for _ in 1:50
        bh_step_all!(bodies, 0.005, 1.0, 0.6, 0.02)
    end
    drift = abs(energy(bodies) - e0) / max(abs(e0), 1e-12)
    bench = bh_benchmark(300)
    Dict{String,Any}("energy_drift" => drift,
                     "err_rms" => bench["err_rms"], "speedup" => bench["speedup"],
                     "all_ok" => drift < 1e-3 && bench["err_rms"] < 0.05 &&
                                 bench["speedup"] > 1.0)
end

"""Perspective projection (OpenGL-style, z in [-1,1]).

Character frame with z-buffer and color.
Progress bar in frame: ICE fill on dark track."""
function bh_benchmark(n_bodies::Int=300)
    rng = MersenneTwister(11)
    bodies = [SimBody(0.0, 0.0, 0.0, 1 / n_bodies, 0.0, 0.0, 0.0, i) for i in 1:n_bodies]
    for b in bodies
        b.x = rand(rng) * 2 - 1; b.y = rand(rng) * 2 - 1
    end
    # прогрев: компилируем оба пути ВНЕ замера
    direct_forces(bodies, 1.0, 0.02)
    warm_tree = build_tree(bodies)
    for i in 1:min(8, n_bodies)
        tree_force(warm_tree, bodies, i, 0.6, 0.02, 1.0)
    end
    t_direct = @elapsed fdir = direct_forces(bodies, 1.0, 0.02)
    tree = build_tree(bodies)
    t_tree = @elapsed ft = [tree_force(tree, bodies, i, 0.6, 0.02, 1.0)
                            for i in eachindex(bodies)]
    err = 0.0
    for i in eachindex(bodies)
        (fx, fy) = ft[i]
        (dx, dy) = fdir[i]
        denom = max(hypot(dx, dy), 1e-12)
        err += hypot(fx - dx, fy - dy) / denom
    end
    Dict{String,Any}("err_rms" => err / n_bodies,
                     "speedup" => t_direct / t_tree,
                     "n" => n_bodies)
end

