# БЛОК: lab/presets.py — каталог 538 объектов + 20 пресетов (embedded JSON)
# ═══════════════════════════════════════════════════════════════════════════

const PALETTE = ["#4FD1C5", "#E8C766", "#A78BFA", "#7DD3FC", "#FB7185",
                 "#34D399", "#FF9A76", "#C8D8D8"]

"""Perspective projection (OpenGL-style, z in [-1,1])."""
function load_catalog()
    d = TV_CATALOG_JSON
    d === nothing && return Dict{String,Any}("count" => 0, "objects" => [])
    d
end

"""bodies: [{position, radius, color, label}]. Returns frame lines."""
function load_presets()
    d = TV_PRESETS_JSON
    d === nothing ? Any[] : d["presets"]
end

"""trails: list of trails (list[(x,y,z)]) per body — drawn as lines."""
function catalog_search(query::String)
    cat = load_catalog()
    q = lowercase(query)
    [o for o in cat["objects"] if
     occursin(q, lowercase(String(get(o, "id", "")))) ||
     occursin(q, lowercase(String(get(o, "name", "")))) ||
     occursin(q, lowercase(String(get(o, "type", ""))))]
end

"""RGB frame with z-buffer."""
function body_from_record(rec::Dict{String,Any}; role="", orbit_km=nothing,
                          angle_deg=0.0, central_mass=nothing, central_radius=nothing)
    m = Float64(rec["mass_kg"])
    r = Float64(rec["radius_km"]) * 1000.0
    a = orbit_km !== nothing ? orbit_km * 1000.0 :
        haskey(rec, "orbit_km") && rec["orbit_km"] !== nothing ?
        Float64(rec["orbit_km"]) * 1000.0 :
        Float64(rec["orbit_au"]) * AU
    Mp = central_mass === nothing ? M_SUN : central_mass
    n = sqrt(G_SI * (Mp + m) / a^3)
    v = n * a
    phi = deg2rad(angle_deg)
    pos = [a * cos(phi), a * sin(phi), 0.0]
    vel = [-v * sin(phi), v * cos(phi), 0.0]
    Body(String(rec["id"]), String(rec["name"]), m, r, pos, vel,
         color=String(get(rec, "color", "#4FD1C5")),
         type=String(get(rec, "type", "body")),
         source=String(get(rec, "source", "embedded catalog")))
end

"""Character frame with z-buffer and color."""
function build_preset(preset_id::String, config::MasterConfig)
    presets = load_presets()
    rec = nothing
    for p in presets
        String(get(p, "id", "")) == preset_id && (rec = p; break)
    end
    rec === nothing && throw(KeyError(preset_id))
    name = String(get(rec, "name", preset_id))

    # модельные пресеты: G = 1
    if preset_id in ("lagrange_triangle", "figure_eight", "vortex_ring_5", "vortex_ring_7")
        cfg = MasterConfig(1.0, config.dt, config.n_steps, config.n_soften,
                           config.allow_unphysical, config.profile,
                           startswith(preset_id, "vortex") ? "native_vortex" :
                           "native_newton", config.root, config.report_formats)
        sc = Scene(cfg; name=name)
        if preset_id == "lagrange_triangle"
            side = 1.0; R = side / sqrt(3)
            omega = sqrt(3.0 / side^3)   # ω = √(Σm/side³), сторона 1
            sc.dt = 0.01
            for k in 0:2
                phi = 2 * pi * k / 3
                add_body!(sc, Body("lagrange_$k", "Лагранж $(k+1)", 1.0, 0.02,
                    [R * cos(phi), R * sin(phi), 0.0],
                    [-omega * R * sin(phi), omega * R * cos(phi), 0.0],
                    color=PALETTE[k+1], type="synthetic", source="Lagrange 1772"))
            end
        elseif preset_id == "figure_eight"
            sc.dt = 0.005
            for (k, (pos, vel)) in enumerate(figure_eight_states())
                add_body!(sc, Body("fe_$k", "Figure-eight $k", 1.0, 0.03,
                    pos, vel, color=PALETTE[k], type="synthetic",
                    source="Chenciner & Montgomery 2000"))
            end
        else  # vortex rings: dt = (2π/ω_N)/240, ω_N = Γ(N−1)/(4πR²)
            n = preset_id == "vortex_ring_7" ? 7 : 5
            omega_n = 1.0 * (n - 1) / (4 * pi * 1.0^2)
            sc.dt = (2 * pi / omega_n) / 240.0
            for k in 0:n-1
                phi = 2 * pi * k / n
                add_body!(sc, Body("v$k", "V$k", 1.0, 0.02,
                    [cos(phi), sin(phi), 0.0], [0.0, 0.0, 0.0],
                    color=PALETTE[(k % 8)+1], type="vortex", source="Kirchhoff",
                    circulation=1.0))
            end
        end
        return sc
    end

    # Теорема 3.1 — специальный пресет
    if preset_id == "theorem31_2pi3"
        sc = Scene(config; name=name)
        sc.dt = 0.005
        for (k, (pos, vel)) in enumerate(theorem31_states(R=1.0).states)
            add_body!(sc, Body("t31_$k", "Хореография $k", 1.0, 0.03, pos, vel,
                color=PALETTE[k], type="synthetic", source="Theorem 3.1"))
        end
        sc.metadata["omega"] = OMEGA31
        sc.metadata["epsilon"] = EPS31
        return sc
    end

    # каталожные пресеты: СИ (логика Python: parent-aware орбиты)
    sc = Scene(config; name=name)
    bodies_spec = rec["bodies"]
    by_id = Dict{String,Any}()
    for o in load_catalog()["objects"]
        by_id[String(o["id"])] = o
    end
    orbit_radius_for(orec, parent_rec, override) = begin
        override !== nothing && return override
        get(orec, "parent", nothing) !== nothing &&
            get(orec, "orbit_km", nothing) isa Real &&
            return Float64(orec["orbit_km"]) * 1000.0
        parent_rec !== nothing && String(get(parent_rec, "type", "")) == "star" &&
            get(orec, "orbit_au", nothing) isa Real &&
            return Float64(orec["orbit_au"]) * AU
        get(orec, "orbit_au", nothing) isa Real &&
            return Float64(orec["orbit_au"]) * AU
        get(orec, "orbit_km", nothing) isa Real &&
            return Float64(orec["orbit_km"]) * 1000.0
        AU  # запасной круг
    end
    place_on_orbit!(satellite, parent, r, phase_deg, incl_deg, G) = begin
        phi = deg2rad(phase_deg)
        incl = deg2rad(incl_deg)
        x = r * cos(phi)
        y = r * sin(phi) * cos(incl)
        z = r * sin(phi) * sin(incl)
        v = sqrt(G * parent.mass / r)
        satellite.position .= parent.position .+ [x, y, z]
        satellite.velocity .= parent.velocity .+
                              [-v * sin(phi), v * cos(phi) * cos(incl),
                               v * cos(phi) * sin(incl)]
        satellite
    end
    satellite_body(orec) = Body(String(orec["id"]), String(orec["name"]),
        Float64(orec["mass_kg"]), Float64(orec["radius_km"]) * 1000.0,
        zeros(3), zeros(3),
        color=String(get(orec, "color", "#4FD1C5")),
        type=String(get(orec, "type", "body")),
        source=String(get(orec, "source", "catalog")))

    parent_body = nothing
    parent_rec = nothing
    orbit_index = 0
    binary_seen = false
    for spec in bodies_spec
        cid = haskey(spec, "catalog") ? String(spec["catalog"]) :
              haskey(spec, "synthetic") ? String(spec["synthetic"]) : ""
        isempty(cid) && continue
        orec = get(by_id, cid, nothing)
        orec === nothing && error("объект $cid отсутствует в каталоге")
        role = String(get(spec, "role", ""))
        if role == "central" && parent_body === nothing
            b = satellite_body(orec)
            b.position .= [0.0, 0.0, 0.0]
            b.velocity .= [0.0, 0.0, 0.0]
            add_body!(sc, b)
            parent_body = b
            parent_rec = orec
            continue
        end
        if role == "binary" && parent_body === nothing
            b = satellite_body(orec)
            b.position .= [0.0, 0.0, 0.0]
            b.velocity .= [0.0, 0.0, 0.0]
            add_body!(sc, b)
            parent_body = b
            parent_rec = orec
            binary_seen = true
            continue
        end
        parent_body === nothing && n_bodies(sc) > 0 &&
            (parent_body = sc.bodies[1]; parent_rec = get(by_id, parent_body.id, orec))
        parent_body === nothing && (parent_body = satellite_body(orec))
        # override: spec.orbit_km или spec.orbit_au (только Real)
        override = get(spec, "orbit_km", nothing) isa Real ?
                   Float64(spec["orbit_km"]) * 1000.0 :
                   (get(spec, "orbit_au", nothing) isa Real ?
                    Float64(spec["orbit_au"]) * AU : nothing)
        r = orbit_radius_for(orec, parent_rec, override)
        phase_raw = get(spec, "phase_deg", 30.0 * (orbit_index + 1))
        phase = phase_raw isa Real ? Float64(phase_raw) : 30.0 * (orbit_index + 1)
        incl_raw = get(spec, "inclination_deg", 0.0)
        incl = incl_raw isa Real ? Float64(incl_raw) : 0.0
        b = satellite_body(orec)
        place_on_orbit!(b, parent_body, r, phase, incl, sc.config.G)
        add_body!(sc, b)
        orbit_index += 1
    end
    if preset_id == "binary_plus_planet" && n_bodies(sc) >= 2
        _fix_binary!(sc, sc.config.G)
    end
    _autotune_dt!(sc)
    sc
end

"""RGB frame with z-buffer."""
function _fix_binary!(sc::Scene, G::Float64)
    a, b = sc.bodies[1], sc.bodies[2]
    total = a.mass + b.mass
    sep = 1.3e13
    omega = sqrt(G * total / sep^3)
    ra = sep * b.mass / total
    rb = sep * a.mass / total
    a.position .= [-ra, 0.0, 0.0]
    a.velocity .= [0.0, -omega * ra, 0.0]
    b.position .= [rb, 0.0, 0.0]
    b.velocity .= [0.0, omega * rb, 0.0]
    if n_bodies(sc) > 2
        p = sc.bodies[3]
        r = 1.646e12
        v = sqrt(G * total / r)
        p.position .= [r, 0.0, 0.0]
        p.velocity .= [0.0, v, 0.0]
    end
    sc
end

"""bodies: [{position, radius, color, label}]. Returns frame lines.
dt = min/200 (floor 1e-9)."""
function _autotune_dt!(sc::Scene)
    isempty(sc.bodies) && return sc
    central = sc.bodies[1]
    for b in sc.bodies
        b.mass > central.mass && (central = b)
    end
    best = Inf
    for b in sc.bodies
        b === central && continue
        r = norm(b.position - central.position)
        r <= 0 && continue
        v = norm(b.velocity)
        v <= 0 && continue
        best = min(best, 2 * pi * r / v)
    end
    isfinite(best) && best > 0 && (sc.dt = max(best / 200.0, 1e-9))
    sc
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: lab/matrix_generator.py — матрицы тел и скалярное масштабирование (v2.1.0)
# ═══════════════════════════════════════════════════════════════════════════

"""Progress bar in frame: ICE fill on dark track."""
const MATRIX_TYPES = [
    ("grid2d", "прямоугольная решётка rows×cols (плоскость xy)"),
    ("grid3d", "кубическая решётка rows×cols×layers (3D)"),
    ("ring",   "кольцо: правильный N-угольник (точное круговое вращение)"),
    ("disk",   "диск: спираль Фибоначчи с золотым углом (2D)"),
    ("shell",  "сферическая оболочка: сфера Фибоначчи (3D)"),
    ("chain",  "цепочка вдоль x — «лестница Кирхгофа» (1D)"),
    ("cloud",  "случайное облако в кубе (3D, воспроизводимый seed)"),
]

const GOLDEN_ANGLE = 2.399963229728653   # рад, спираль Фибоначчи

"""Character frame with z-buffer and color.

Title bar at top of frame: dark panel + gold text.
Radius encoded by symbol density + spot size: r_px < 1 — single
Character frame with z-buffer and color."""
function matrix_dims(matrix::String; rows::Int=4, cols::Int=4, layers::Int=1,
                     scale::Real=1.0)
    k = max(Float64(scale), 0.0)
    ri(x) = max(1, round(Int, x * k))
    if matrix == "grid2d"
        (rows=ri(rows), cols=ri(cols), layers=1)
    elseif matrix == "grid3d"
        (rows=ri(rows), cols=ri(cols), layers=ri(layers))
    else
        (rows=max(1, round(Int, rows * cols * k)), cols=1, layers=1)
    end
end

"""Perspective projection (OpenGL-style, z in [-1,1])."""
function matrix_positions(matrix::String, dims; extent::Real=1.0, seed::Int=42)
    R = Float64(extent)
    pos = Vector{Vector{Float64}}()
    d_min = R
    if matrix == "grid2d"
        r, c = dims.rows, dims.cols
        s = R / max(r - 1, c - 1, 1)
        for i in 1:r, j in 1:c
            push!(pos, [(i - (r + 1) / 2) * s, (j - (c + 1) / 2) * s, 0.0])
        end
        d_min = s
    elseif matrix == "grid3d"
        r, c, l = dims.rows, dims.cols, dims.layers
        s = R / max(r - 1, c - 1, l - 1, 1)
        for i in 1:r, j in 1:c, k in 1:l
            push!(pos, [(i - (r + 1) / 2) * s, (j - (c + 1) / 2) * s,
                        (k - (l + 1) / 2) * s])
        end
        d_min = s
    elseif matrix == "ring"
        n = dims.rows
        rad = R / 2
        for i in 0:n-1
            phi = 2 * pi * i / n
            push!(pos, [rad * cos(phi), rad * sin(phi), 0.0])
        end
        d_min = 2 * rad * sin(pi / max(n, 2))
    elseif matrix == "disk"
        n = dims.rows
        rad = R / 2
        for i in 1:n
            push!(pos, [rad * sqrt(i / n) * cos(i * GOLDEN_ANGLE),
                        rad * sqrt(i / n) * sin(i * GOLDEN_ANGLE), 0.0])
        end
        d_min = rad / max(sqrt(n), 1)
    elseif matrix == "shell"
        n = dims.rows
        rad = R / 2
        for i in 1:n
            y = 1 - 2 * (i - 0.5) / n
            rr = sqrt(max(1 - y * y, 0.0))
            phi = i * GOLDEN_ANGLE
            push!(pos, [rad * rr * cos(phi), rad * rr * sin(phi), rad * y])
        end
        d_min = 2 * rad / max(sqrt(n), 1)
    elseif matrix == "chain"
        n = dims.rows
        s = R / max(n - 1, 1)
        for i in 1:n
            push!(pos, [(i - (n + 1) / 2) * s, 0.0, 0.0])
        end
        d_min = s
    else  # cloud
        rng = MersenneTwister(seed)
        for _ in 1:dims.rows
            push!(pos, [rand(rng) * R - R / 2, rand(rng) * R - R / 2,
                        rand(rng) * R - R / 2])
        end
        d_min = R / max(cbrt(dims.rows), 1)
    end
    (pos=pos, d_min=max(d_min, 1e-12))
end

"""symbol density; larger — disk of symbols.
Perspective projection (OpenGL-style, z in [-1,1])."""
function ring_omega(n::Int, m::Real, G::Real, R::Real)
    n < 2 && return 0.0
    s = 0.0
    for k in 1:n-1
        s += 1 / sin(pi * k / n)
    end
    sqrt(G * m / (4 * R^3) * s)
end

"""RGB frame with z-buffer."""
history_bytes(n::Int, steps::Int, every::Int=1) =
    (6 * n + 1) * 8 * (div(steps, max(every, 1)) + 2)

"""Title bar at top of frame: dark panel + gold text."""
suggest_history_every(n::Int, steps::Int, budget_mb::Real=512) =
    max(1, ceil(Int, history_bytes(n, steps, 1) / (1024 * 1024 * budget_mb)))

"""bodies: [{position, radius, color, label}]. Returns frame lines.

RGB frame with z-buffer.
RGB frame with z-buffer.
trails: list of trails (list[(x,y,z)]) per body — drawn as lines.
bodies: [{position, radius, color, label}]. Returns frame lines.
trails: list of trails (list[(x,y,z)]) per body — drawn as lines.
RGB frame with z-buffer.
RGB frame with z-buffer.
Vertices and triangles of UV-sphere (poles along y)."""
function build_matrix_scene(matrix::String; rows::Int=4, cols::Int=4, layers::Int=1,
                            scale::Real=1.0, extent::Real=1.0, mass::Real=1.0,
                            spin::Real=0.1, dt::Real=0.0, circulation::Real=1.0,
                            seed::Int=42, engine::String="native_newton",
                            cfg::Union{MasterConfig,Nothing}=nothing,
                            allow_unphysical::Bool=false)
    known = first.(MATRIX_TYPES)
    matrix in known || throw(ArgumentError(
        "неизвестная матрица «$matrix» (доступны: $(join(known, ", ")))"))
    (rows >= 1 && cols >= 1 && layers >= 1) ||
        throw(ArgumentError("rows/cols/layers должны быть ≥ 1"))
    scale > 0 || throw(ArgumentError("scale должен быть > 0"))
    extent > 0 || throw(ArgumentError("extent должен быть > 0"))
    mass > 0 || throw(ArgumentError("mass должен быть > 0"))

    base = cfg === nothing ? from_profile("quick") : cfg
    dims = matrix_dims(matrix; rows=rows, cols=cols, layers=layers, scale=scale)
    layout = matrix_positions(matrix, dims; extent=extent, seed=seed)
    pos = layout.pos
    n = length(pos)
    m = Float64(mass)
    Γ = Float64(circulation)

    # unphysical-протокол: N ≥ порога Хавелока требует флага
    hav = havelok_threshold()
    (hav > 0 && n >= hav && !allow_unphysical && !base.allow_unphysical) &&
        throw(UnphysicalConfiguration(
            "N=$n ≥ $hav: порог Хавелока; --allow-unphysical / --havelok 0"))

    # движок: неизвестное имя → честный fallback-протокол (событие ниже)
    eng_fallback = !(engine in available_engines() || engine == "native_newton")
    engine = eng_fallback ? "native_newton" : engine
    # смягчение: матрицы содержат близкие пары — поднимаем soften до
    # доли d_min (честно фиксируем в протоколе events), если профиль меньше
    soften_eff = max(base.n_soften, 0.1 * layout.d_min)
    icfg = MasterConfig(1.0, dt > 0 ? Float64(dt) : 0.01, base.n_steps,
                        soften_eff, allow_unphysical || base.allow_unphysical,
                        base.profile, engine, base.root, base.report_formats)
    sc = Scene(icfg; name="Матрица $(matrix) ×$(scale)")
    eng_fallback && push!(sc.events,
        "fallback движок: недоступен → native_newton (матричный генератор)")
    soften_eff > base.n_soften && push!(sc.events,
        @sprintf("soften поднят %.2e → %.2e (матрица: близкие пары, d_min=%.2e)",
                 base.n_soften, soften_eff, layout.d_min))

    # радиус тел: без перекрытий для решёток/кольца/цепочки
    r_body = matrix in ("grid2d", "grid3d", "ring", "chain") ?
             0.4 * layout.d_min : 0.05 * extent / max(sqrt(n), 1)
    r_body = max(min(r_body, 0.4 * extent), 1e-9)

    is_vortex = engine == "native_vortex"
    # спин: -1 = авто (вириальное вращение ω = √(GM)/R^1.5 — край почти
    # круговой), 0 = без вращения, >0 = заданная угловая скорость
    spin_eff = Float64(spin)
    if spin_eff < 0 && matrix != "ring" && !is_vortex
        M_tot = m * n
        spin_eff = sqrt(M_tot) / (extent / 2)^1.5
    end
    ω_ring = matrix == "ring" && !is_vortex ?
             ring_omega(n, m, 1.0, extent / 2) : 0.0
    for (i, p) in enumerate(pos)
        if is_vortex
            vel = [0.0, 0.0, 0.0]
        elseif matrix == "ring"
            vel = [-ω_ring * p[2], ω_ring * p[1], 0.0]
        else
            vel = [-spin_eff * p[2], spin_eff * p[1], 0.0]
        end
        add_body!(sc, Body("m$i", "$(matrix)_$i", m, r_body, p, vel,
                           color=PALETTE[(i - 1) % 8 + 1],
                           type=matrix == "ring" && is_vortex ? "vortex" : "matrix",
                           source="matrix:$matrix", circulation=is_vortex ? Γ : 0.0))
    end

    # автоподбор dt: минимум из времени свободного падения системы
    # и парного времени по ближайшей паре d_min (иначе плотные диски
    # с близкими парами взрываются на первом же шаге)
    if dt > 0
        sc.dt = Float64(dt)
    elseif is_vortex
        omega_max = abs(Γ) / (2 * pi * layout.d_min^2)
        sc.dt = (2 * pi / max(omega_max, 1e-9)) / 2000
    elseif matrix == "ring"
        sc.dt = ω_ring > 0 ? 2 * pi / ω_ring / 200 : 0.01
    else
        t_ff = sqrt(extent^3 / (1.0 * m * n))          # G = 1
        t_pair = sqrt(layout.d_min^3 / (2.0 * m))       # ближайшая пара
        sc.dt = max(0.02 * min(t_ff, t_pair), 1e-12)
    end
    sc.metadata["matrix"] = Dict{String,Any}(
        "type" => matrix, "rows" => rows, "cols" => cols, "layers" => layers,
        "scale" => Float64(scale), "extent" => Float64(extent),
        "mass" => m, "spin" => Float64(spin), "dt" => Float64(dt),
        "circulation" => Γ, "seed" => seed, "engine" => engine,
        "n" => n)
    sc
end

"""symbol density; larger — disk of symbols.
Progress bar in frame: ICE fill on dark track."""
function scale_matrix_scene(sc::Scene, k::Real; cfg::Union{MasterConfig,Nothing}=nothing)
    md = get(sc.metadata, "matrix", nothing)
    md === nothing && throw(ArgumentError(
        "сцена «$(sc.name)» не матричная (нет параметров matrix)"))
    Float64(k) > 0 || throw(ArgumentError("множитель k должен быть > 0"))
    build_matrix_scene(String(md["type"]);
        rows=Int(md["rows"]), cols=Int(md["cols"]), layers=Int(md["layers"]),
        scale=Float64(md["scale"]) * Float64(k), extent=Float64(md["extent"]),
        mass=Float64(md["mass"]), spin=Float64(md["spin"]), dt=Float64(md["dt"]),
        circulation=Float64(md["circulation"]), seed=Int(md["seed"]),
        engine=String(md["engine"]), cfg=cfg,
        allow_unphysical=sc.config.allow_unphysical || sc.unphysical_flag)
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: lab/kepler.py — кеплеровская механика: элементы ↔ состояние, Ламберт
# ═══════════════════════════════════════════════════════════════════════════

"""RGB frame with z-buffer."""
function solve_kepler(M::Float64, e::Float64)
    M = mod(M, 2 * pi)
    E = e < 0.8 ? M : pi
    for _ in 1:100
        f = E - e * sin(E) - M
        fp = 1.0 - e * cos(E)
        dE = f / fp
        E -= dE
        abs(dE) < 1e-12 && break
    end
    E
end

"""Radius encoded by symbol density + spot size: r_px < 1 — single"""
kepler_period(a, mu) = 2 * pi * sqrt(a^3 / mu)

"""Perspective projection (OpenGL-style, z in [-1,1])."""
function elements_to_state(a, e, i_deg, Omega_deg, omega_deg, M_deg, mu)
    i = deg2rad(i_deg); Om = deg2rad(Omega_deg); w = deg2rad(omega_deg)
    M = deg2rad(M_deg)
    E = solve_kepler(M, e)
    # координаты в орбитальной плоскости
    xa = a * (cos(E) - e)
    ya = a * sqrt(1 - e^2) * sin(E)
    r = hypot(xa, ya)
    n_mean = sqrt(mu / a^3)
    Edot = n_mean / (1 - e * cos(E))
    vxa = -a * Edot * sin(E)
    vya = a * sqrt(1 - e^2) * Edot * cos(E)
    # повороты: ω → i → Ω
    cw, sw = cos(w), sin(w)
    cO, sO = cos(Om), sin(Om)
    ci, si = cos(i), sin(i)
    x = (cO * cw - sO * sw * ci) * xa + (-cO * sw - sO * cw * ci) * ya
    y = (sO * cw + cO * sw * ci) * xa + (-sO * sw + cO * cw * ci) * ya
    z = (sw * si) * xa + (cw * si) * ya
    vx = (cO * cw - sO * sw * ci) * vxa + (-cO * sw - sO * cw * ci) * vya
    vy = (sO * cw + cO * sw * ci) * vxa + (-sO * sw + cO * cw * ci) * vya
    vz = (sw * si) * vxa + (cw * si) * vya
    ([x, y, z], [vx, vy, vz])
end

"""Title bar at top of frame: dark panel + gold text."""
function state_to_elements(r, v, mu)
    R = norm(r)
    V = norm(v)
    a = 1.0 / (2.0 / R - V^2 / mu)
    h = cross(r, v)
    evec = cross(v, h) / mu - r / R
    e = norm(evec)
    i = acos(clamp(h[3] / norm(h), -1.0, 1.0))
    nvec = cross([0.0, 0.0, 1.0], h)
    Om = norm(nvec) > 1e-12 ? atan(nvec[2], nvec[1]) : 0.0
    Om < 0 && (Om += 2 * pi)
    w = 0.0
    if e > 1e-10 && norm(nvec) > 1e-12
        w = acos(clamp(dot(nvec, evec) / (norm(nvec) * e), -1.0, 1.0))
        evec[3] < 0 && (w = 2 * pi - w)
    elseif e > 1e-10
        w = atan(evec[2], evec[1])
    end
    nu = 0.0
    if e > 1e-10
        nu = acos(clamp(dot(evec, r) / (e * R), -1.0, 1.0))
        dot(r, v) < 0 && (nu = 2 * pi - nu)
    end
    (a, e, rad2deg(i), rad2deg(Om), rad2deg(w), rad2deg(nu))
end

"""Progress bar in frame: ICE fill on dark track."""
vis_viva(r, a, mu) = sqrt(mu * (2 / r - 1 / a))

"""trails: list of trails (list[(x,y,z)]) per body — drawn as lines."""
function lambert(r1::Vector{Float64}, r2::Vector{Float64}, dt::Float64, mu::Float64;
                 prograde::Bool=true, tol::Float64=1e-10, max_iter::Int=200)
    R1 = norm(r1); R2 = norm(r2)
    cross_z = r1[1] * r2[2] - r1[2] * r2[1]
    cos_dnu = clamp(dot(r1, r2) / (R1 * R2), -1.0, 1.0)
    dnu = acos(cos_dnu)
    if prograde
        cross_z < 0 && (dnu = 2 * pi - dnu)
    else
        cross_z > 0 && (dnu = 2 * pi - dnu)
    end
    A = sin(dnu) * sqrt(R1 * R2 / (1 - cos(dnu)))
    A == 0 && return nothing
    c2c(x) = x > 0 ? (1 - cos(sqrt(x))) / x :
             x < 0 ? (cosh(sqrt(-x)) - 1) / (-x) : 0.5
    y(z) = R1 + R2 + A * (z * c2c(z) - 1) / sqrt(c2c(z))
    F(z) = (y(z) / c2c(z))^(3 / 2) * c2c(z) + A * sqrt(y(z)) - sqrt(mu) * dt
    z0 = 0.0
    F0 = F(z0)
    z = F0 > 0 ? z0 + 0.1 : z0 - 0.1
    for _ in 1:max_iter
        Fz = F(z)
        abs(Fz) < tol && break
        # численная производная
        h = 1e-6
        dF = (F(z + h) - F(z - h)) / (2 * h)
        abs(dF) < 1e-14 && break
        z -= Fz / dF
    end
    yz = y(z)
    f = 1 - yz / R1
    g = A * sqrt(yz / mu)
    gdot = 1 - yz / R2
    v1 = (r2 .- f .* r1) ./ g
    v2 = (gdot .* r2 .- r1) ./ g
    (v1, v2)
end

