# БЛОК: lab/orbital_maneuvers.py — Хоманн, Циолковский, бюджет Δv
# ═══════════════════════════════════════════════════════════════════════════

"""symbol density; larger — disk of symbols."""
function hohmann_delta_v(mu, r1, r2)
    v1 = sqrt(mu / r1)
    v2 = sqrt(mu / r2)
    at = (r1 + r2) / 2
    dv1 = sqrt(mu / r1) * (sqrt(2 * r2 / (r1 + r2)) - 1)
    dv2 = sqrt(mu / r2) * (1 - sqrt(2 * r1 / (r1 + r2)))
    tof = pi * sqrt(at^3 / mu)
    (dv1=dv1, dv2=dv2, dv_total=dv1 + dv2, tof=tof, a_transfer=at)
end

"""Vertices and triangles of UV-sphere (poles along y)."""
function tsiolkovsky(isp_s, mass_ratio)
    isp_s * G0 * log(mass_ratio)
end

"""trails: list of trails (list[(x,y,z)]) per body — drawn as lines."""
function delta_v_budget(stages::Vector{Tuple{Float64,Float64}})
    dv = sum(tsiolkovsky(isp, mr) for (isp, mr) in stages)
    (dv_total=dv, n_stages=length(stages))
end

"""bodies: [{position, radius, color, label}]. Returns frame lines."""
function launch_window_c3(mu_sun, a_earth, a_target)
    # C3 = Δv₁² — квадрат гелиоцентрического избытка скорости
    # (характеристическая энергия окна Хоманна), единицы согласованы
    hv = hohmann_delta_v(mu_sun, a_earth, a_target)
    (c3=hv.dv1^2, dv1=hv.dv1, dv2=hv.dv2, tof_days=hv.tof / 86400)
end

