const TH31_OMEGA = OMEGA31
const TH31_EPS = EPS31

"""Character frame with z-buffer and color."""
function figure_eight_states()
    x1 = 0.97000436; y1 = -0.24338733
    vx3 = -0.93240737; vy3 = -0.86473146
    [([x1, y1, 0.0], [-vx3 / 2, -vy3 / 2, 0.0]),
     ([-x1, -y1, 0.0], [-vx3 / 2, -vy3 / 2, 0.0]),
     ([0.0, 0.0, 0.0], [vx3, vy3, 0.0])]
end

"""Progress bar in frame: ICE fill on dark track."""
function theorem31_states(; R=1.0, m=1.0, G=1.0)
    omega = TH31_OMEGA
    states = [(R * [cos(2 * pi * k / 3), sin(2 * pi * k / 3), 0.0],
               -omega * R * [sin(2 * pi * k / 3), cos(2 * pi * k / 3), 0.0])
              for k in 0:2]
    (states=states, omega=omega, epsilon=TH31_EPS, R=R, m=m, G=G)
end

"""Title bar at top of frame: dark panel + gold text."""
function kirchhoff_ring(n::Int, gamma::Float64=1.0, R::Float64=1.0)
    omega = gamma * (n - 1) / (4 * pi * R^2)
    period = 2 * pi / omega
    (radius=R, omega=omega, period=period)
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: lab/halo_orbits.py — CR3BP: точки Лагранжа, интеграл Якоби, Лиссажу
# ═══════════════════════════════════════════════════════════════════════════

"""bodies: [{position, radius, color, label}]. Returns frame lines."""
function cr3bp_deriv(state::Vector{Float64}, mu::Float64)
    x, y, z, vx, vy, vz = state
    r1 = hypot(x + mu, y, z)          # до большего тела (в −μ)
    r2 = hypot(x - (1 - mu), y, z)    # до меньшего (в 1−μ)
    ax = 2 * vy + x - (1 - mu) * (x + mu) / r1^3 - mu * (x - 1 + mu) / r2^3
    ay = -2 * vx + y - (1 - mu) * y / r1^3 - mu * y / r2^3
    az = -(1 - mu) * z / r1^3 - mu * z / r2^3
    [vx, vy, vz, ax, ay, az]
end

"""Title bar at top of frame: dark panel + gold text."""
function jacobi_constant(state::Vector{Float64}, mu::Float64)
    x, y, z = state[1:3]
    r1 = hypot(x + mu, y, z)
    r2 = hypot(x - (1 - mu), y, z)
    Omega = (1 - mu) / r1 + mu / r2 + 0.5 * (x^2 + y^2)
    v2 = state[4]^2 + state[5]^2 + state[6]^2
    2 * Omega - v2
end

"""Radius encoded by symbol density + spot size: r_px < 1 — single"""
_collinear_rhs(x, mu) = begin
    r1 = x + mu
    r2 = x - (1 - mu)
    x - (1 - mu) * (x + mu) / abs(r1)^3 - mu * (x - 1 + mu) / abs(r2)^3
end

"""Radius encoded by symbol density + spot size: r_px < 1 — single
Character frame with z-buffer and color."""
function lagrange_points(mu::Float64)
    # скобки: L1 ∈ (−μ, 1−μ), L2 ∈ (1−μ, ∞), L3 ∈ (−∞, −μ) — f меняет знак
    _bisect(f, a, b) = begin
        fa = f(a)
        for _ in 1:200
            m = (a + b) / 2
            fm = f(m)
            abs(fm) < 1e-14 && return m
            (sign(fm) == sign(fa)) ? (a = m; fa = fm) : (b = m)
        end
        (a + b) / 2
    end
    f = x -> _collinear_rhs(x, mu)
    x_l1 = _bisect(f, -mu + 1e-6, 1.0 - mu - 1e-6)
    x_l2 = _bisect(f, 1.0 - mu + 1e-6, 3.0)
    x_l3 = _bisect(f, -3.0, -mu - 1e-6)
    Dict{String,Any}(
        "L1" => [x_l1, 0.0, 0.0], "L2" => [x_l2, 0.0, 0.0], "L3" => [x_l3, 0.0, 0.0],
        "L4" => [0.5 - mu, sqrt(3) / 2, 0.0], "L5" => [0.5 - mu, -sqrt(3) / 2, 0.0])
end

"""Title bar at top of frame: dark panel + gold text."""
function _cr3bp_rk4(state, dt, mu)
    k1 = cr3bp_deriv(state, mu)
    k2 = cr3bp_deriv(state .+ dt / 2 .* k1, mu)
    k3 = cr3bp_deriv(state .+ dt / 2 .* k2, mu)
    k4 = cr3bp_deriv(state .+ dt .* k3, mu)
    state .+ dt / 6 .* (k1 .+ 2 .* k2 .+ 2 .* k3 .+ k4)
end

"""Radius encoded by symbol density + spot size: r_px < 1 — single"""
function jacobi_drift(mu, state0::Vector{Float64}, dt::Float64, n_steps::Int)
    st = copy(state0)
    C0 = jacobi_constant(st, mu)
    dmax = 0.0
    for _ in 1:n_steps
        st = _cr3bp_rk4(st, dt, mu)
        dmax = max(dmax, abs(jacobi_constant(st, mu) - C0))
    end
    dmax
end

"""Perspective projection (OpenGL-style, z in [-1,1]).
equations, with ωz = √(−Ωzz) vertical."""
function linear_frequencies(mu::Float64)
    pts = lagrange_points(mu)
    x0 = pts["L2"][1]
    r1 = hypot(x0 + mu, 0, 0)
    r2 = hypot(x0 - (1 - mu), 0, 0)
    base = 1 - (1 - mu) / r1^3 - mu / r2^3
    Omega_xx = base + 3 * ((1 - mu) * (x0 + mu)^2 / r1^5 +
                           mu * (x0 - 1 + mu)^2 / r2^5)
    Omega_yy = base
    Omega_zz = -(1 - mu) / r1^3 - mu / r2^3
    # характеристическое: λ⁴ + (4 − Ωxx − Ωyy)λ² + Ωxx·Ωyy = 0
    b = 4 - Omega_xx - Omega_yy
    c = Omega_xx * Omega_yy
    disc = b^2 - 4 * c
    if disc < 0
        return (omega_xy=NaN, omega_z=NaN)
    end
    lam2_1 = (-b + sqrt(disc)) / 2
    lam2_2 = (-b - sqrt(disc)) / 2
    neg_root = min(lam2_1, lam2_2)   # колебательный корень λ² < 0
    omega_xy = sqrt(max(-neg_root, 0.0))
    omega_z = sqrt(max(-Omega_zz, 0.0))
    (omega_xy=omega_xy, omega_z=omega_z)
end

"""Vertices and triangles of UV-sphere (poles along y)."""
function lissajous_around_l2(mu::Float64, Axy::Float64, Az::Float64, n_steps::Int=600)
    fr = linear_frequencies(mu)
    pts = lagrange_points(mu)
    x0, y0, _ = pts["L2"]
    out = Vector{Vector{Float64}}(undef, n_steps)
    for k in 0:n_steps-1
        t = k * 0.05
        x = x0 + Axy * cos(fr.omega_xy * t)
        y = y0 + Axy * (fr.omega_xy / (2 * 1.0)) * sin(fr.omega_xy * t)
        z = Az * sin(fr.omega_z * t + pi / 2)
        out[k+1] = [x, y, z]
    end
    out
end

"""Character frame with z-buffer and color."""
function self_check_halo_orbits()
    mu = 0.012150585609
    pts = lagrange_points(mu)
    x_l1 = pts["L1"][1]; x_l2 = pts["L2"][1]; x_l3 = pts["L3"][1]
    l1_ok = abs(x_l1 - 0.836915) < 0.002
    l2_ok = abs(x_l2 - 1.155682) < 0.003
    l3_ok = abs(x_l3 + 1.005063) < 0.005
    l4_ok = abs(pts["L4"][1] - (0.5 - mu)) < 1e-12 &&
            abs(pts["L4"][2] - sqrt(3) / 2) < 1e-12
    l1 = pts["L1"]
    state0 = [l1[1], l1[2] + 0.01, 0.0, 0.0, 0.05, 0.0]
    n_coarse = 600
    drift_coarse = jacobi_drift(mu, state0, 0.005, n_coarse)
    drift_fine = jacobi_drift(mu, state0, 0.0025, 2 * n_coarse)
    ratio = drift_coarse / max(drift_fine, 1e-18)
    jacobi_ok = drift_fine < 1e-5 && 6.0 < ratio < 40.0
    Dict{String,Any}("x_L1" => x_l1, "x_L2" => x_l2, "x_L3" => x_l3,
                     "L1_ok" => l1_ok, "L2_ok" => l2_ok, "L3_ok" => l3_ok,
                     "L4_ok" => l4_ok, "jacobi_drift" => drift_fine,
                     "drift_ratio" => ratio, "jacobi_ok" => jacobi_ok,
                     "all_ok" => l1_ok && l2_ok && l3_ok && l4_ok && jacobi_ok,
                     "note" => "NASA SSERD: L1 = 0.836915, L2 = 1.155682; " *
                               "отношение дрейфов при dt/2 ~ 2⁴ (RK4)")
end

