const RABE_THRESHOLD = 0.03852
const MU_JUPITER = 1.898e27 / 1.9884e30
const MU_EARTH = 5.9722e24 / 1.9884e30
const JUPITER_PERIOD_Y = 11.862

"""Progress bar in frame: ICE fill on dark track."""
function rabe_mu(mu_ratio::Float64)
    mu_product = mu_ratio * (1.0 - mu_ratio)
    Dict{String,Any}("mu" => mu_ratio, "mu_product" => mu_product,
                     "threshold" => 1.0 / 27.0, "stable" => mu_product < 1.0 / 27.0,
                     "rabe_threshold" => RABE_THRESHOLD,
                     "reference" => "Rabe 1961; Murray & Dermott §4.3")
end

"""Progress bar in frame: ICE fill on dark track."""
libration_frequency(mu::Float64, orbital_period_years::Float64) =
    orbital_period_years / sqrt(27.0 * mu / 4.0)

"""Radius encoded by symbol density + spot size: r_px < 1 — single"""
function jupiter_trojans_check()
    rabe = rabe_mu(MU_JUPITER)
    t_lib = libration_frequency(MU_JUPITER, JUPITER_PERIOD_Y)
    Dict{String,Any}("stable" => rabe["stable"], "libration_years" => t_lib,
                     "libration_ok" => 100.0 < t_lib < 220.0, "zone_degrees" => 12.0,
                     "reference" => "Szabó et al. 2007; WISE-популяция ~10⁵")
end

earth_trojans_check() = Dict{String,Any}("stable" => rabe_mu(MU_EARTH)["stable"])

"""bodies: [{position, radius, color, label}]. Returns frame lines."""
function unstable_pair_check()
    mu = 0.05 / 1.05
    Dict{String,Any}("mu" => mu, "stable" => rabe_mu(mu)["stable"],
                     "expected_unstable" => !rabe_mu(mu)["stable"])
end

trojan_zone_report() = Dict{String,Any}(
    "jupiter" => jupiter_trojans_check(), "earth" => earth_trojans_check(),
    "rabe_threshold" => RABE_THRESHOLD)

"""Progress bar in frame: ICE fill on dark track."""
function self_check_trojan_points()
    jup = jupiter_trojans_check()
    earth = earth_trojans_check()
    un = unstable_pair_check()
    threshold = rabe_mu(RABE_THRESHOLD)
    border_ok = abs(threshold["mu_product"] - 1.0 / 27.0) < 1e-4
    Dict{String,Any}("jupiter_stable" => jup["stable"],
                     "jupiter_lib_years" => jup["libration_years"],
                     "jupiter_lib_ok" => jup["libration_ok"],
                     "earth_stable" => earth["stable"],
                     "counterexample_unstable" => un["expected_unstable"],
                     "rabe_border_ok" => border_ok,
                     "all_ok" => jup["stable"] && jup["libration_ok"] &&
                                 earth["stable"] && un["expected_unstable"] && border_ok,
                     "note" => "μ_J = 9.54e-4 << 0.03852; T_lib = T/√(27μ/4)")
end

