# БЛОК: lab/resonances.py — положения p:q, Кирквуд, Wisdom, сверхпериоды TTV
# ═══════════════════════════════════════════════════════════════════════════

const KIRKWOOD_GAPS = Dict(
    "3:1" => (2.502, 3, 1), "5:2" => (2.824, 5, 2),
    "7:3" => (2.958, 7, 3), "2:1" => (3.279, 2, 1))
const LAPLACE_PERIODS = Dict("io" => 1.769138, "europa" => 3.551181,
                             "ganymede" => 7.154553)  # сутки (NASA)

"""symbol density; larger — disk of symbols."""
resonance_location(a_planet::Float64, p::Int, q::Int) =
    a_planet * (q / p)^(2.0 / 3.0)

"""symbol density; larger — disk of symbols."""
function kirkwood_check(a_jupiter::Float64=5.2038)
    out = Dict{String,Any}()
    ok = true
    for (name, (a_pub, p, q)) in KIRKWOOD_GAPS
        a_calc = resonance_location(a_jupiter, p, q)
        out[name] = Dict("published_au" => a_pub, "computed_au" => a_calc,
                         "err_au" => a_calc - a_pub)
        ok = ok && abs(a_calc - a_pub) < 0.015
    end
    Dict{String,Any}("gaps" => out, "all_ok" => ok,
                     "note" => "a = a_J·(q/p)^{2/3}")
end

"""Character frame with z-buffer and color."""
function wisdom_chaotic_zone(m_planet, m_star, a_planet)
    mu = m_planet / (3.0 * m_star)
    delta_ratio = 1.5 * mu^(2.0 / 7.0)
    Dict{String,Any}("mu" => mu, "delta_ratio" => delta_ratio,
                     "delta_au" => delta_ratio * a_planet,
                     "inner_edge_au" => a_planet * (1 - delta_ratio),
                     "outer_edge_au" => a_planet * (1 + delta_ratio),
                     "reference" => "Wisdom 1980, AJ 85, 1122")
end

jupiter_zone_check() = begin
    res = wisdom_chaotic_zone(1.898e27, 1.9884e30, 5.2038)
    Dict{String,Any}("delta_au" => res["delta_au"],
                     "ok" => 0.5 < res["delta_au"] < 1.3)
end

"""Character frame with z-buffer and color."""
function laplace_ratios()
    r1 = LAPLACE_PERIODS["europa"] / LAPLACE_PERIODS["io"]
    r2 = LAPLACE_PERIODS["ganymede"] / LAPLACE_PERIODS["io"]
    Dict{String,Any}("io_europa" => r1, "io_ganymede" => r2,
                     "near_2_1" => abs(r1 - 2.0) < 0.02,
                     "near_4_1" => abs(r2 - 4.0) < 0.05,
                     "note" => "фаза φ = λ₃ − 3λ₂ + 2λ₁ либрирует (Yoder 1979)")
end

"""Vertices and triangles of UV-sphere (poles along y)."""
resonance_angle(lam_body, lam_perturber, varpi_body, p::Int, q::Int) =
    rad2deg(mod(p * lam_perturber - q * lam_body + (q - p) * varpi_body, 2 * pi))

"""Title bar at top of frame: dark panel + gold text."""
function is_librating(angles_deg::Vector{Float64}, tol::Float64=60.0)
    length(angles_deg) < 3 && return false
    best = Inf
    for center in (0.0, 180.0)
        wrapped = [((a - center + 180.0) % 360.0) - 180.0 for a in angles_deg]
        best = min(best, maximum(wrapped) - minimum(wrapped))
    end
    best < tol
end

"""Radius encoded by symbol density + spot size: r_px < 1 — single"""
function ttv_super_period(p_inner::Float64, p_outer::Float64, j::Int)
    rate = j / p_outer - (j - 1) / p_inner
    abs(rate) < 1e-15 ? Inf : 1.0 / abs(rate)
end

"""Vertices and triangles of UV-sphere (poles along y)."""
function ttv_pair_report(p_inner::Float64, p_outer::Float64)
    ratio = p_outer / p_inner
    best_j, best_delta = 2, Inf
    for j in 2:7
        d = abs(ratio - j / (j - 1))
        if d < best_delta
            best_j, best_delta = j, d
        end
    end
    Dict{String,Any}("period_ratio" => ratio, "resonance" => "$(best_j):$(best_j - 1)",
                     "offset" => best_delta,
                     "super_period_days" => ttv_super_period(p_inner, p_outer, best_j),
                     "reference" => "Lithwick, Xie & Wu 2012, ApJ 761, 122")
end

kepler_9_check() = begin
    rep = ttv_pair_report(19.2389, 38.9076)
    merge(Dict{String,Any}(rep),
          Dict{String,Any}("plausible" => 1000.0 < rep["super_period_days"] < 4000.0))
end

"""RGB frame with z-buffer."""
function self_check_resonances()
    kw = kirkwood_check()
    lap = laplace_ratios()
    jz = jupiter_zone_check()
    k9 = kepler_9_check()
    lib = [rad2deg(sin(t * 0.1)) for t in 0:19]
    circ = [mod(t * 7.5, 360.0) for t in 0:19]
    ok = kw["all_ok"] && lap["near_2_1"] && lap["near_4_1"] && jz["ok"] &&
         k9["plausible"] && is_librating(lib) && !is_librating(circ)
    Dict{String,Any}("kirkwood_ok" => kw["all_ok"],
                     "laplace_2_1" => lap["io_europa"], "laplace_4_1" => lap["io_ganymede"],
                     "wisdom_delta_au" => jz["delta_au"],
                     "k9_super_period" => k9["super_period_days"],
                     "libration_ok" => is_librating(lib),
                     "circulation_ok" => !is_librating(circ), "all_ok" => ok)
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: lab/tissot.py — параметр Тиссерана, классы Levison 1996
# ═══════════════════════════════════════════════════════════════════════════

struct SmallBody
    name::String
    a::Float64
    e::Float64
    i_deg::Float64
end

const HALLEY = SmallBody("1P/Галлея", 17.834, 0.96714, 162.26)
const P67 = SmallBody("67P/Ч-Г", 3.4630, 0.64102, 7.04)
const HALDA = SmallBody("2P/Энке", 2.2157, 0.84833, 11.78)

"""Character frame with z-buffer and color."""
tisserand(a, e, i_deg; a_planet=5.2038) =
    a_planet / a + 2.0 * sqrt(a_planet / a * (1 - e * e)) * cosd(i_deg)

"""Progress bar in frame: ICE fill on dark track."""
function classify_jupiter(T_j::Float64)
    cls = T_j > 3.0 ? "астероид (динамически)" :
          T_j > 2.0 ? "комета семейства Юпитера (JFC)" :
          "тип Галлея / долгопериодическая (HTC/LPC)"
    Dict{String,Any}("class_name" => cls, "reference" => "Levison 1996, ASPC 149, 171")
end

halley_check() = begin
    t = tisserand(HALLEY.a, HALLEY.e, HALLEY.i_deg)
    merge(Dict{String,Any}("name" => HALLEY.name, "T_j" => round(t, digits=3),
                           "expected" => -0.61, "ok" => abs(t + 0.61) < 0.1),
          Dict{String,Any}(classify_jupiter(t)))
end

jfc_check() = begin
    t = tisserand(P67.a, P67.e, P67.i_deg)
    merge(Dict{String,Any}("name" => P67.name, "T_j" => round(t, digits=3)),
          Dict{String,Any}(classify_jupiter(t)))
end

encke_check() = begin
    t = tisserand(HALDA.a, HALDA.e, HALDA.i_deg)
    merge(Dict{String,Any}("name" => HALDA.name, "T_j" => round(t, digits=3)),
          Dict{String,Any}(classify_jupiter(t)))
end

"""trails: list of trails (list[(x,y,z)]) per body — drawn as lines."""
function tisserand_under_pr(a0, t_pr_s, t_s; a_planet=5.2038)
    if t_s <= 0
        return Dict{String,Any}("T" => tisserand(a0, 0.0, 0.0; a_planet=a_planet),
                                "dT_dt" => 0.0)
    end
    a_t = a0 * exp(-t_s / max(t_pr_s, 1e-9))
    T_now = a_planet / a_t
    dT_dt = (-a_planet / a_t^2) * (-a_t / t_pr_s)
    Dict{String,Any}("a_now_au" => a_t, "T" => T_now, "dT_dt" => dT_dt,
                     "note" => "Wyatt & Whipple 1950: a = a₀e^{−t/t_PR}")
end

"""RGB frame with z-buffer."""
function self_check_tissot()
    t_ceres = tisserand(2.7675, 0.0785, 10.59)
    ceres_ok = abs(t_ceres - 4.573) < 0.01
    t_coorbital = tisserand(5.2038, 0.0, 0.0; a_planet=5.2038)
    coorbital_ok = abs(t_coorbital - 3.0) < 1e-12
    h = halley_check()
    halley_class_ok = startswith(h["class_name"], "тип Галлея")
    j = jfc_check()
    e = encke_check()
    Dict{String,Any}("T_ceres" => round(t_ceres, digits=4), "ceres_ok" => ceres_ok,
                     "T_coorbital" => t_coorbital, "coorbital_ok" => coorbital_ok,
                     "halley_T" => h["T_j"], "halley_class_ok" => halley_class_ok,
                     "p67_T" => j["T_j"], "encke_T" => e["T_j"],
                     "all_ok" => ceres_ok && coorbital_ok && halley_class_ok)
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: lab/tides.py — приливы: поднятие, трение, кругализация, Козаи-Лидов
# ═══════════════════════════════════════════════════════════════════════════

struct TidalSystem
    M_primary::Float64      # кг
    R_primary::Float64      # м
    M_satellite::Float64
    R_satellite::Float64
    a::Float64              # м
    e::Float64
end

mu_primary(ts::TidalSystem) = G_SI * ts.M_primary

"""Progress bar in frame: ICE fill on dark track."""
tidal_elevation(ts::TidalSystem) =
    (ts.M_satellite / ts.M_primary) * (ts.R_primary / ts.a)^3 * ts.R_primary

"""RGB frame with z-buffer."""
function tidal_da_dt(ts::TidalSystem, Q::Float64, k2::Float64)
    n = sqrt(G_SI * (ts.M_primary + ts.M_satellite) / ts.a^3)
    f_e = 1.0 + 15.0 / 2.0 * ts.e^2 + 45.0 / 8.0 * ts.e^4 + 5.0 / 16.0 * ts.e^6
    3.0 * (k2 / Q) * (ts.M_satellite / ts.M_primary) *
        (ts.R_primary / ts.a)^5 * ts.a * n * f_e
end

"""Synchronous orbit radius: a_sync = (GM_p·(T_spin/2π)²)^{1/3}."""
synchronous_radius(ts::TidalSystem, spin_period::Float64=86400.0) =
    (mu_primary(ts) * (spin_period / (2 * pi))^2)^(1.0 / 3.0)

"""trails: list of trails (list[(x,y,z)]) per body — drawn as lines."""
function tidal_da_signed(ts::TidalSystem, Q::Float64, k2::Float64, spin_period=86400.0)
    da = tidal_da_dt(ts, Q, k2)
    ts.a > synchronous_radius(ts, spin_period) ? da : -da
end

"""bodies: [{position, radius, color, label}]. Returns frame lines."""
function tidal_lock_time(ts::TidalSystem, Q::Float64, k2::Float64,
                         spin0::Float64=2 * pi / 86400.0)
    I = 0.4 * ts.M_satellite * ts.R_satellite^2
    omega_sync = sqrt(G_SI * ts.M_primary / ts.a^3)
    n = omega_sync
    t = I * omega_sync * spin0 / (3 * G_SI * k2 * ts.M_primary^2 *
        ts.R_satellite^3 / (Q * ts.a^6) * n) |> abs
    t / YEAR_S  # годы
end

"""trails: list of trails (list[(x,y,z)]) per body — drawn as lines."""
function moon_recession_check()
    ts = TidalSystem(5.9722e24, 6.371e6, 7.342e22, 1.7375e6, 3.844e8, 0.0549)
    da = tidal_da_signed(ts, 12.0, 0.299)
    cm_per_year = da * (365.25 * 86400) * 100
    Dict{String,Any}("da_dt_m_s" => da, "cm_per_year" => cm_per_year,
                     "observed_cm_per_year" => 3.82,
                     "note" => "LLR: 3.82±0.07 см/год (NASA)")
end

"""trails: list of trails (list[(x,y,z)]) per body — drawn as lines.
Ė = (21/2)·(k2/Q)·G·M_p²·R_s⁵·n·e²/a⁶, k2=0.30, Q=12."""
function tidal_heating(M_primary, M_satellite, R_satellite, a, e; k2=0.015, Q=100.0)
    n = sqrt(G_SI * (M_primary + M_satellite) / a^3)
    (21.0 / 2.0) * (k2 / Q) * G_SI * M_primary^2 * R_satellite^5 * n * e^2 / a^6
end

function io_heating_check()
    p = tidal_heating(1.898e27, 8.932e22, 1.8216e6, 4.217e8, 0.0041;
                      k2=0.30, Q=12.0)
    Dict{String,Any}("power_watts" => p, "observed_watts" => 1.0e14,
                     "ratio" => p / 1.0e14, "ok" => 0.3 < p / 1.0e14 < 5.0,
                     "note" => "вулканизм Ио — Morabito et al. 1979")
end

"""RGB frame with z-buffer."""
function kozai_emax(i_deg::Float64)
    i = deg2rad(i_deg)
    crit = sqrt(1 - 3 * cos(i)^2)  # < 0 при i < 39.2° — Козаи не активен
    if isnan(crit) || crit < 0
        return Dict{String,Any}("active" => false, "e_max" => 0.0,
                                "threshold_deg" => 39.2307)
    end
    e_max = sqrt(1.0 - 5.0 / 3.0 * cos(i)^2)
    Dict{String,Any}("active" => true, "e_max" => e_max,
                     "threshold_deg" => 39.2307,
                     "note" => "Lidov 1962; Kozai 1962; √(1−e²)cos i = const")
end

"""Progress bar in frame: ICE fill on dark track."""
function self_check_tides()
    moon = moon_recession_check()
    io = io_heating_check()
    kz = kozai_emax(60.0)
    ok = 0.5 < moon["cm_per_year"] < 20.0 && io["ok"] && kz["active"]
    Dict{String,Any}("moon_cm_per_year" => moon["cm_per_year"],
                     "io_power_w" => io["power_watts"], "io_ok" => io["ok"],
                     "kozai_emax_60" => kz["e_max"], "kozai_ok" => kz["active"],
                     "all_ok" => ok)
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: lab/radiation.py — Пойнтинг-Робертсон, Ярковский, световой парус
# ═══════════════════════════════════════════════════════════════════════════

const SOLAR_CONSTANT = 1361.0  # Вт/м² на 1 а.е. (TSI)

"""Character frame with z-buffer and color."""
function pr_lifetime(radius_m, density, a_m; L=L_SUN, Q_pr=1.0)
    4 * pi * C2 * density * radius_m * a_m^2 / (3 * L * max(Q_pr, 1e-9))
end

pr_lifetime_years(radius_m, density, a_m; L=L_SUN, Q_pr=1.0) =
    pr_lifetime(radius_m, density, a_m; L=L, Q_pr=Q_pr) / YEAR_S

"""Progress bar in frame: ICE fill on dark track."""
function yarkovsky_drift_rate(radius_m::Float64, density::Float64=2500.0;
                              a_au::Float64=1.0, semi_major_axis_m=nothing)
    # da/dt ≈ (4/9)·(Φ/(ρ·c_th))·cos φ — параметризация Bottke et al. 2006;
    # характерный масштаб: da/dt ~ 1e-4 а.е./млн лет для D~100 м
    da_dt_typical = 1e-4 * (100.0 / radius_m) / (a_au^2)
    da_dt_typical
end

"""Progress bar in frame: ICE fill on dark track."""
function solar_sail_acceleration(area::Float64, mass::Float64;
                                 a_au::Float64=1.0, Q::Float64=1.0)
    I = SOLAR_CONSTANT / a_au^2
    2 * I * Q / (C_LIGHT * mass / area)
end

"""Perspective projection (OpenGL-style, z in [-1,1])."""
function self_check_radiation()
    t_pr = pr_lifetime_years(100e-6, 3000.0, AU)
    yark = yarkovsky_drift_rate(50.0)
    sail = solar_sail_acceleration(1000.0, 10.0)
    ok = 1e5 < t_pr < 5e5 && 1e-5 < yark < 1e-3 && 0 < sail < 1e-2
    Dict{String,Any}("grain_pr_lifetime_years" => t_pr,
                     "yarkovsky_50m_au_per_myr" => yark,
                     "sail_accel_m_s2_1kg_m2" => sail, "all_ok" => ok)
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: lab/relativity.py — 1PN EIH, 2PN, Лензе-Тирринг, ISCO, Шварцшильд
# ═══════════════════════════════════════════════════════════════════════════

"""symbol density; larger — disk of symbols."""
function eih_acceleration(r, v, M::Float64, eta::Float64=0.0)
    r_n = norm(r)
    v_n2 = dot(v, v)
    n = r / r_n
    rv = dot(r, v)
    GM = G_SI * M
    # Wagoner-Will: a_1PN = GM/r²·[n(1+3η·v²/c² − 6GM/rc² …) − …]
    a_n = -GM / r_n^2
    c2 = C2
    term1 = 1.0 + (3.0 * eta * v_n2 + GM / r_n * (4.0 + 2.0 * eta)) / c2
    term2 = (4.0 - 2.0 * eta) * rv / c2
    a = a_n .* (n .* term1 .- (v ./ r_n) .* term2)
    a
end

"""Title bar at top of frame: dark panel + gold text."""
function perihelion_precession(m1, m2, a, e; order::Int=1)
    M = m1 + m2
    eta = m1 * m2 / M^2
    factor = G_SI * M / (a * (1 - e^2) * C2)
    delta = 6.0 * pi * factor
    if order >= 2
        delta += (3.0 * pi / 2.0) * (7.0 - eta) * factor^2
    end
    period = 2.0 * pi * sqrt(a^3 / (G_SI * M))
    n_orbits = 100.0 * 365.25 * 86400.0 / period
    delta * n_orbits * (180.0 / pi) * 3600.0
end

"""Progress bar in frame: ICE fill on dark track."""
function mercury_precession()
    val = perihelion_precession(1.9884e30, 3.301e23, 5.7909e10, 0.205630)
    val2 = perihelion_precession(1.9884e30, 3.301e23, 5.7909e10, 0.205630; order=2)
    Dict{String,Any}("name" => "Меркурий",
                     "pn1_arcsec_century" => val, "pn2_arcsec_century" => val2,
                     "gr_reference" => 42.98,
                     "note" => "1PN (Шварцшильд) — излишек 43″/век")
end

"""Progress bar in frame: ICE fill on dark track."""
isco_radius(M::Float64) = 6.0 * G_SI * M / C2

"""RGB frame with z-buffer."""
schwarzschild_radius(M::Float64) = 2.0 * G_SI * M / C2

"""Radius encoded by symbol density + spot size: r_px < 1 — single"""
function lense_thirring_precession(M, R, spin_period, a, e=0.0, incl_deg=90.0)
    omega_spin = 2.0 * pi / spin_period
    k_struct = M > 1e29 ? 0.06 : 0.33
    J = k_struct * M * R * R * omega_spin
    Omega_LT = 2.0 * G_SI * J / (C2 * a^3 * (1 - e^2)^1.5)
    Omega_eff = Omega_LT * cosd(incl_deg)
    arcsec_century = Omega_eff * (100 * 365.25 * 86400) * (180 / pi) * 3600
    Dict{String,Any}("Omega_rad_s" => Omega_eff,
                     "arcsec_per_century" => arcsec_century,
                     "angular_momentum" => J)
end

"""Vertices and triangles of UV-sphere (poles along y)."""
function self_check_relativity()
    m = mercury_precession()
    ok_mercury = abs(m["pn1_arcsec_century"] - m["gr_reference"]) < 0.5
    r_isco = isco_radius(1e30)
    r_expected = 6.0 * G_SI * 1e30 / C2
    ok_isco = abs(r_isco - r_expected) / r_expected < 1e-9
    rs = schwarzschild_radius(1.9884e30)
    ok_rs = abs(rs - 2953.4) / 2953.4 < 0.01
    Dict{String,Any}("mercury_1pn" => m["pn1_arcsec_century"], "mercury_ok" => ok_mercury,
                     "isco_ok" => ok_isco, "sun_rs_m" => rs, "sun_rs_ok" => ok_rs,
                     "all_ok" => ok_mercury && ok_isco && ok_rs)
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: lab/chaos.py — FLI, Пуанкаре, Ласкар (частотный анализ)
# ═══════════════════════════════════════════════════════════════════════════

henon_heiles_deriv(y, _t) =
    [y[3], y[4], -y[1] - 2 * y[1] * y[2], -y[2] - y[1]^2 + y[2]^2]
harmonic_deriv(y, _t) = [y[2], -y[1]]

"""trails: list of trails (list[(x,y,z)]) per body — drawn as lines."""
function fli(deriv, y0, dt, n_steps; delta0=1e-8, renorm_every=10)
    n = length(y0)
    y = collect(float.(y0))
    y_p = collect(float.(y0)); y_p[1] += delta0
    dist = delta0
    for step in 1:n_steps
        k1 = deriv(y, 0.0); k2 = deriv(y .+ dt / 2 .* k1, 0.0)
        k3 = deriv(y .+ dt / 2 .* k2, 0.0); k4 = deriv(y .+ dt .* k3, 0.0)
        y = y .+ dt / 6 .* (k1 .+ 2 .* k2 .+ 2 .* k3 .+ k4)
        l1 = deriv(y_p, 0.0); l2 = deriv(y_p .+ dt / 2 .* l1, 0.0)
        l3 = deriv(y_p .+ dt / 2 .* l2, 0.0); l4 = deriv(y_p .+ dt .* l3, 0.0)
        y_p = y_p .+ dt / 6 .* (l1 .+ 2 .* l2 .+ 2 .* l3 .+ l4)
        d = norm(y_p - y)
        if d > 0 && step % renorm_every == 0
            y_p = y .+ (y_p - y) * (delta0 / d)
        end
        dist = d
    end
    (fli=log10(max(dist, delta0) / delta0), history=nothing)
end

fli_classify(value::Float64, dt::Float64, n_steps::Int) = begin
    t_end = dt * n_steps
    value < log10(t_end) + 1.0 ? "регулярная" : "хаотическая"
end

"""Perspective projection (OpenGL-style, z in [-1,1])."""
function poincare_section(y0::Vector{Float64}, dt::Float64, n_steps::Int)
    pts = Tuple{Float64,Float64}[]
    y = copy(y0)
    prev_y = y[2]
    for _ in 1:n_steps
        k1 = henon_heiles_deriv(y, 0.0)
        k2 = henon_heiles_deriv(y .+ dt / 2 .* k1, 0.0)
        k3 = henon_heiles_deriv(y .+ dt / 2 .* k2, 0.0)
        k4 = henon_heiles_deriv(y .+ dt .* k3, 0.0)
        y = y .+ dt / 6 .* (k1 .+ 2 .* k2 .+ 2 .* k3 .+ k4)
        if prev_y < 0.0 && y[2] >= 0.0 && y[4] > 0.0
            push!(pts, (y[1], y[3]))
        end
        prev_y = y[2]
    end
    pts
end

"""bodies: [{position, radius, color, label}]. Returns frame lines.
via a DFT with apodization — the highest-power mode)."""
function laskar_frequency(signal::Vector{Float64}, dt::Float64)
    n = length(signal)
    window = [0.5 - 0.5 * cos(2 * pi * k / (n - 1)) for k in 0:n-1]
    w = signal .* window
    freqs = [(k) / (n * dt) for k in 0:n÷2]
    pw = Float64[]
    for k in 0:n÷2
        re = sum(w[i+1] * cos(2 * pi * k * i / n) for i in 0:n-1)
        im = sum(w[i+1] * sin(2 * pi * k * i / n) for i in 0:n-1)
        push!(pw, re^2 + im^2)
    end
    imax = argmax(pw[2:end]) + 1
    (freq=freqs[imax], power=pw[imax])
end

"""Vertices and triangles of UV-sphere (poles along y)."""
function self_check_chaos()
    fli_reg = fli(henon_heiles_deriv, [0.1, 0.0, 0.0, 0.05], 0.02, 2000).fli
    fli_chaos = fli(henon_heiles_deriv, [0.1, 0.2, 0.4, 0.3], 0.02, 2000).fli
    fli_osc = fli(harmonic_deriv, [1.0, 0.0], 0.02, 2000).fli
    ordering_ok = fli_chaos > fli_reg >= fli_osc - 1.0
    pts = poincare_section([0.1, 0.2, 0.4, 0.3], 0.02, 3000)
    Dict{String,Any}("fli_hh_regular" => fli_reg, "fli_hh_chaotic" => fli_chaos,
                     "fli_oscillator" => fli_osc, "ordering_ok" => ordering_ok,
                     "poincare_points" => length(pts),
                     "poincare_ok" => length(pts) > 5,
                     "all_ok" => ordering_ok && length(pts) > 5)
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: lab/collisions.py — столкновения: слияние, отскок, фрагментация
# ═══════════════════════════════════════════════════════════════════════════

"""Perspective projection (OpenGL-style, z in [-1,1])."""
function merge_bodies(m1, v1, m2, v2)
    m_tot = m1 + m2
    v_new = (m1 .* v1 .+ m2 .* v2) ./ m_tot
    (mass=m_tot, velocity=v_new)
end

"""Progress bar in frame: ICE fill on dark track."""
function bounce_1d(m1, v1, m2, v2, restitution::Float64=1.0)
    # 1D упруго-неупругое столкновение
    v_rel = v2 - v1
    u1 = ((m1 - restitution * m2) * v1 + (1 + restitution) * m2 * v2) / (m1 + m2)
    u2 = ((m2 - restitution * m1) * v2 + (1 + restitution) * m1 * v1) / (m1 + m2)
    (u1=u1, u2=u2)
end

"""RGB frame with z-buffer."""
function fragment(mass, velocity::Vector{Float64}, n_fragments::Int)
    masses = [mass / n_fragments for _ in 1:n_fragments]
    rng = MersenneTwister(42)
    vs = [velocity .+ (rand(rng, 3) .- 0.5) .* 2.0 for _ in 1:n_fragments]
    # центрирование: суммарный импульс = исходный
    p0 = mass .* velocity
    p_frag = sum(masses[i] .* vs[i] for i in 1:n_fragments)
    vs = [vs[i] .+ (p0 .- p_frag) ./ mass for i in 1:n_fragments]
    [(mass=masses[i], velocity=vs[i]) for i in 1:n_fragments]
end

"""symbol density; larger — disk of symbols."""
function self_check_collisions()
    m1, m2 = 1.0, 2.0
    v1 = [2.0, 0.0, 0.0]; v2 = [-1.0, 0.0, 0.0]
    mrg = merge_bodies(m1, v1, m2, v2)
    p_before = m1 .* v1 .+ m2 .* v2
    momentum_ok = norm(mrg.mass .* mrg.velocity - p_before) < 1e-12

    b = bounce_1d(1.0, 2.0, 1.0, 0.0, 1.0)
    momentum_bounce = abs((b.u1 + b.u2) - (2.0 + 0.0)) < 1e-12
    energy_bounce = abs((0.5 * b.u1^2 + 0.5 * b.u2^2) - (0.5 * 4.0)) < 1e-12

    frags = fragment(3.0, [1.0, 0.0, 0.0], 3)
    p_frag = sum(frags[i].mass .* frags[i].velocity for i in eachindex(frags))
    fragment_ok = norm(p_frag .- 3.0 .* [1.0, 0.0, 0.0]) < 1e-10

    Dict{String,Any}("merge_momentum_ok" => momentum_ok,
                     "bounce_momentum_ok" => momentum_bounce,
                     "bounce_energy_ok" => energy_bounce,
                     "fragment_momentum_ok" => fragment_ok,
                     "n_fragments" => length(frags),
                     "all_ok" => momentum_ok && momentum_bounce &&
                                 energy_bounce && fragment_ok)
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: lab/hamiltonian_split.py — расщепление гамильтониана (DR/KD)
# ═══════════════════════════════════════════════════════════════════════════

"""symbol density; larger — disk of symbols."""
struct HamiltonianSplit
    T_only::Bool   # true: K свободен от q, T от p
end

"""bodies: [{position, radius, color, label}]. Returns frame lines."""
function split_leapfrog_step(q::Vector{Float64}, p::Vector{Float64},
                             grad_T::Function, grad_V::Function, dt::Float64)
    p1 = p .- dt / 2 .* grad_V(q)        # kick
    q1 = q .+ dt .* grad_T(p1)           # drift
    p2 = p1 .- dt / 2 .* grad_V(q1)      # kick
    (q1, p2)
end

"""Vertices and triangles of UV-sphere (poles along y)."""
function self_check_hamiltonian()
    grad_T(p) = p
    grad_V(q) = q
    q, p = [1.0], [0.0]
    H0 = 0.5 * (q[1]^2 + p[1]^2)
    dmax = 0.0
    dt = 0.01
    for _ in 1:1000
        q, p = split_leapfrog_step(q, p, grad_T, grad_V, dt)
        dmax = max(dmax, abs(0.5 * (q[1]^2 + p[1]^2) - H0))
    end
    # осцилляция сохраняется
    ok = dmax < 1e-3 && norm(q) > 1e-6
    Dict{String,Any}("drift_max" => dmax, "periods_integrated" => 1000 * dt / (2 * pi),
                     "all_ok" => ok)
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: lab/grid_fields.py — векторные поля на сетке: дивергенция, ротор
# ═══════════════════════════════════════════════════════════════════════════

"""Character frame with z-buffer and color."""
function grid_field_stats(f, x0::Float64, x1::Float64, y0::Float64, y1::Float64;
                          n::Int=50)
    h = (x1 - x0) / (n - 1)
    div_max = 0.0; curl_max = 0.0
    for i in 2:n-1, j in 2:n-1
        x = x0 + (i - 1) * h; y = y0 + (j - 1) * h
        (u1, v1) = f(x + h, y)
        (u0, v0) = f(x - h, y)
        (u_, v_up) = f(x, y + h)
        (u_dn, v_dn) = f(x, y - h)
        div = (u1 - u0 + v_up - v_dn) / (2 * h)
        curl = (u_ - u_dn - (v1 - v0)) / (2 * h)
        div_max = max(div_max, abs(div))
        curl_max = max(curl_max, abs(curl))
    end
    (div_max=div_max, curl_max=curl_max)
end

"""Title bar at top of frame: dark panel + gold text."""
function self_check_grid_fields()
    s1 = grid_field_stats((x, y) -> (-y, x), -1.0, 1.0, -1.0, 1.0)  # вращение
    s2 = grid_field_stats((x, y) -> (x, y), -1.0, 1.0, -1.0, 1.0)   # источник: div=2
    ok = s1.curl_max > 1.5 && s2.div_max > 1.5
    Dict{String,Any}("rotation_curl" => s1.curl_max, "sink_div" => s2.div_max,
                     "all_ok" => ok)
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: lab/spacecraft.py — кватернионы, ПИД, маховики
# ═══════════════════════════════════════════════════════════════════════════

"""Title bar at top of frame: dark panel + gold text."""
function quat_mul(a::Vector{Float64}, b::Vector{Float64})
    w1, x1, y1, z1 = a
    w2, x2, y2, z2 = b
    [w1*w2 - x1*x2 - y1*y2 - z1*z2,
     w1*x2 + x1*w2 + y1*z2 - z1*y2,
     w1*y2 - x1*z2 + y1*w2 + z1*x2,
     w1*z2 + x1*y2 - y1*x2 + z1*w2]
end

"""Character frame with z-buffer and color."""
function quat_from_axis_angle(axis::Vector{Float64}, angle::Float64)
    n = norm(axis)
    n == 0 && return [1.0, 0.0, 0.0, 0.0]
    a = axis ./ n
    s = sin(angle / 2)
    [cos(angle / 2), a[1]*s, a[2]*s, a[3]*s]
end

"""symbol density; larger — disk of symbols."""
function quat_rotate(q::Vector{Float64}, v::Vector{Float64})
    qv = [0.0, v[1], v[2], v[3]]
    q_conj = [q[1], -q[2], -q[3], -q[4]]
    res = quat_mul(quat_mul(q, qv), q_conj)
    res[2:4]
end

"""trails: list of trails (list[(x,y,z)]) per body — drawn as lines."""
mutable struct PIDController
    kp::Float64; ki::Float64; kd::Float64
    integral::Float64
    integral_limit::Float64
    prev_err::Float64
end

function pid_step!(pid::PIDController, err::Float64, dt::Float64)
    pid.integral += err * dt
    pid.integral = clamp(pid.integral, -pid.integral_limit, pid.integral_limit)
    deriv = (err - pid.prev_err) / max(dt, 1e-12)
    pid.prev_err = err
    pid.kp * err + pid.ki * pid.integral + pid.kd * deriv
end

"""Radius encoded by symbol density + spot size: r_px < 1 — single"""
mutable struct ReactionWheel
    inertia::Float64
    omega::Float64
    h_max::Float64
end

function wheel_torque!(w::ReactionWheel, torque_cmd::Float64, dt::Float64)
    h = w.inertia * w.omega + torque_cmd * dt
    h = clamp(h, -w.h_max, w.h_max)
    w.omega = h / w.inertia
    w.inertia * w.omega - (w.inertia * w.omega - h)  # реализованный момент
end

"""Perspective projection (OpenGL-style, z in [-1,1])."""
function self_check_spacecraft()
    # поворот на 90° вокруг z
    q = quat_from_axis_angle([0.0, 0.0, 1.0], pi / 2)
    v = quat_rotate(q, [1.0, 0.0, 0.0])
    quat_ok = norm(v .- [0.0, 1.0, 0.0]) < 1e-12
    # норма сохраняется
    norm_ok = abs(norm(q) - 1.0) < 1e-12
    # ПИД: ошибка → 0
    pid = PIDController(2.0, 0.5, 0.1, 0.0, 10.0, 0.0)
    err = 1.0
    for _ in 1:500
        t = pid_step!(pid, err, 0.01)
        err = err - t * 0.01  # простая инерция
    end
    pid_ok = abs(err) < 0.05
    # маховик
    w = ReactionWheel(0.01, 0.0, 0.1)
    for _ in 1:100
        wheel_torque!(w, 0.001, 0.01)
    end
    wheel_ok = abs(w.omega) <= 0.1 / 0.01 + 1e-9
    Dict{String,Any}("quat_ok" => quat_ok, "quat_norm_ok" => norm_ok,
                     "pid_ok" => pid_ok, "wheel_ok" => wheel_ok,
                     "all_ok" => quat_ok && norm_ok && pid_ok && wheel_ok)
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: realism/planetary_systems.py — Hill, TRAPPIST-1, зона жизни
# ═══════════════════════════════════════════════════════════════════════════

"""Vertices and triangles of UV-sphere (poles along y)."""
hill_radius(m_sat, m_primary, a) = a * (m_sat / (3.0 * m_primary))^(1.0 / 3.0)

"""Vertices and triangles of UV-sphere (poles along y)."""
equilibrium_temperature(a_m, L_star; albedo=0.3, emissivity=1.0) =
    (L_star * (1 - albedo) / (16 * pi * emissivity * SIGMA_SB * a_m^2))^0.25

"""symbol density; larger — disk of symbols."""
insolation_in_earth_units(a_m, L_star) = (L_star / L_SUN) / (a_m / AU)^2

"""Progress bar in frame: ICE fill on dark track."""
trappist_T_eq() = equilibrium_temperature(0.02925 * AU, 0.000553 * L_SUN, albedo=0.0)

"""Character frame with z-buffer and color."""
function habitable_zone(L_star::Float64)
    # эффективная T_eff=5780K-коэффициенты, консервативный диапазон
    s_inner = 1.107   # runaway greenhouse (для S⊕-нормировки)
    s_outer = 0.356   # maximum greenhouse
    d = sqrt(L_star / L_SUN)
    (inner_au=d * sqrt(1.0 / s_inner), outer_au=d * sqrt(1.0 / s_outer))
end

"""Progress bar in frame: ICE fill on dark track."""
function trappist_chain_check()
    periods = (1.51087081, 2.4218233, 4.049610, 6.099615, 9.206690, 12.35294, 18.767)  # сут
    # соседние отношения около 8:5, 5:3, 3:2, 3:2, 4:3, 3:2 (Agol 2021)
    ratios = [periods[i+1] / periods[i] for i in 1:6]
    chain_ok = count(r -> 1.2 < r < 2.2, ratios) >= 5
    Dict{String,Any}("periods_days" => collect(periods), "ratios" => ratios,
                     "chain_ok" => chain_ok)
end

"""symbol density; larger — disk of symbols."""
function self_check_planetary_systems()
    t_eq = trappist_T_eq()
    teq_ok = abs(t_eq - 249.0) < 15.0
    r_h = hill_radius(5.9722e24, 1.9884e30, AU)
    hill_ok = 0.009 < r_h / AU < 0.011   # ≈ 0.01 а.е.
    chain = trappist_chain_check()
    hz = habitable_zone(0.000553 * L_SUN)
    e_in_hz = hz.inner_au < 0.02925 < hz.outer_au
    ok = teq_ok && hill_ok && chain["chain_ok"]
    Dict{String,Any}("trappist_T_eq" => t_eq, "teq_ok" => teq_ok,
                     "earth_hill_au" => r_h / AU, "hill_ok" => hill_ok,
                     "trappist_chain_ok" => chain["chain_ok"],
                     "e_in_hz" => e_in_hz, "all_ok" => ok)
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: realism/stellar.py — главная последовательность, Рош, классы
# ═══════════════════════════════════════════════════════════════════════════

const T_SUN = 5772.0

"""symbol density; larger — disk of symbols."""
function ms_luminosity(m_solar::Float64)
    if m_solar < 0.43
        0.23 * m_solar^2.3
    elseif m_solar < 2.0
        m_solar^4.0
    elseif m_solar < 55.0
        1.4 * m_solar^3.5
    else
        32000.0 * m_solar
    end
end

"""trails: list of trails (list[(x,y,z)]) per body — drawn as lines."""
ms_radius(m_solar::Float64) = m_solar < 1.0 ? m_solar^0.8 : m_solar^0.57

"""T_eff = T☉·(L/R²)^{1/4}."""
ms_teff(m_solar::Float64) = T_SUN * (ms_luminosity(m_solar) / ms_radius(m_solar)^2)^0.25

"""τ_MS ≈ 10·M/L Gyr."""
ms_lifetime_gyr(m_solar::Float64) = 10.0 * m_solar / max(ms_luminosity(m_solar), 1e-8)

"""trails: list of trails (list[(x,y,z)]) per body — drawn as lines."""
function spectral_class(t::Float64)
    if t > 30000; "O"
    elseif t > 10000; "B"
    elseif t > 7500; "A"
    elseif t > 6000; "F"
    elseif t > 5200; "G"
    elseif t > 3700; "K"
    else "M"
    end
end

"""symbol density; larger — disk of symbols."""
roche_limit_fluid(rho_p, rho_s) = 2.44 * (rho_p / rho_s)^(1.0 / 3.0)

"""Progress bar in frame: ICE fill on dark track."""
function roche_lobe(q::Float64)
    x = q^(2.0 / 3.0)
    0.49 * x / (0.6 * x + log(1.0 + x))
end

"""Progress bar in frame: ICE fill on dark track."""
function self_check_stellar()
    sun_l = ms_luminosity(1.0)
    sun_ok = abs(sun_l - 1.0) < 0.01 && spectral_class(ms_teff(1.0)) == "G"
    o_life = ms_lifetime_gyr(30.0)
    o_ok = 0.0005 < o_life < 0.02
    rd_life = ms_lifetime_gyr(0.1)
    rd_ok = rd_life > 500.0   # красные карлики: сотни млрд лет по M/L-шкале
    rl = roche_lobe(1.0)
    rl_ok = abs(rl - 0.379) < 0.01
    Dict{String,Any}("sun_ok" => sun_ok, "ostar_life_gyr" => o_life, "ostar_ok" => o_ok,
                     "red_dwarf_life_gyr" => rd_life, "red_dwarf_ok" => rd_ok,
                     "roche_lobe_q1" => rl, "roche_ok" => rl_ok,
                     "all_ok" => sun_ok && o_ok && rd_ok && rl_ok)
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: realism/sky_coordinates.py — JD, GMST, LST, координаты, прецессия
# ═══════════════════════════════════════════════════════════════════════════

const OBLIQUITY_J2000 = deg2rad(23.4392911)

"""bodies: [{position, radius, color, label}]. Returns frame lines."""
function julian_date(dt::DateTime)
    # алгоритм Флиндерса-Петри через дней от эпохи
    y = year(dt); mo = month(dt); d = day(dt)
    hh = hour(dt) + minute(dt) / 60.0 + second(dt) / 3600.0
    if mo <= 2
        y -= 1; mo += 12
    end
    a = fld(y, 100)
    b = 2 - a + fld(a, 4)
    jd = floor(365.25 * (y + 4716)) + floor(30.6001 * (mo + 1)) + d + b - 1524.5
    jd + hh / 24.0
end

"""bodies: [{position, radius, color, label}]. Returns frame lines."""
function gmst_hours(jd::Float64)
    T = (jd - J2000_JD) / 36525.0
    g = 280.46061837 + 360.98564736629 * (jd - J2000_JD) + 0.000387933 * T^2 - T^3 / 38710000.0
    mod(g, 360.0) / 15.0
end

"""symbol density; larger — disk of symbols."""
lst_hours(jd::Float64, lon_deg::Float64) = mod(gmst_hours(jd) + lon_deg / 15.0, 24.0)

"""Title bar at top of frame: dark panel + gold text."""
function equatorial_to_ecliptic(ra_rad::Float64, dec_rad::Float64)
    x = cos(dec_rad) * cos(ra_rad)
    y = cos(dec_rad) * sin(ra_rad)
    z = sin(dec_rad)
    ye = y * cos(OBLIQUITY_J2000) + z * sin(OBLIQUITY_J2000)
    ze = -y * sin(OBLIQUITY_J2000) + z * cos(OBLIQUITY_J2000)
    (lambda=atan(ye, x), beta=asin(ze))
end

"""bodies: [{position, radius, color, label}]. Returns frame lines."""
function equatorial_to_horizontal(ra_rad::Float64, dec_rad::Float64,
                                  lat_deg::Float64, lst_h::Float64)
    ha = deg2rad(lst_h * 15.0) - ra_rad
    lat = deg2rad(lat_deg)
    alt = asin(sin(dec_rad) * sin(lat) + cos(dec_rad) * cos(lat) * cos(ha))
    az = atan2r(-cos(dec_rad) * cos(lat) * sin(ha),
                sin(dec_rad) * cos(lat) - cos(dec_rad) * sin(lat) * cos(ha))
    (azimuth=mod(az, 2 * pi), altitude=alt)
end

atan2r(y, x) = atan(y, x)

"""Radius encoded by symbol density + spot size: r_px < 1 — single"""
function angular_separation(ra1, dec1, ra2, dec2)
    acos(clamp(sin(dec1) * sin(dec2) + cos(dec1) * cos(dec2) * cos(ra1 - ra2),
               -1.0, 1.0))
end

"""Progress bar in frame: ICE fill on dark track."""
function parse_ra(s::String)
    m = match(r"(\d+)h\s*(\d+)m\s*([\d.]+)s", s)
    m === nothing && return NaN
    deg = (parse(Float64, m[1]) + parse(Float64, m[2]) / 60.0 +
           parse(Float64, m[3]) / 3600.0) * 15.0
    deg2rad(deg)
end

"""Title bar at top of frame: dark panel + gold text."""
function parse_dec(s::String)
    m = match(r"([+-]?)(\d+)°\s*(\d+)′\s*([\d.]+)″", s)
    m === nothing && return NaN
    deg = parse(Float64, m[2]) + parse(Float64, m[3]) / 60.0 +
          parse(Float64, m[4]) / 3600.0
    deg2rad(m[1] == "-" ? -deg : deg)
end

"""Vertices and triangles of UV-sphere (poles along y)."""
function self_check_sky_coordinates()
    jd = julian_date(DateTime(2024, 3, 20, 12, 0, 0))
    g = gmst_hours(jd)
    # RA Веги ≈ 18h36m = 279.234°, Dec = +38.78°
    ra = parse_ra("18h 36m 56.3s"); dec = parse_dec("+38° 47′ 01″")
    lst = mod(g, 24.0)
    hor = equatorial_to_horizontal(ra, dec, 55.0, lst)
    # эклиптика Солнца в равноденствие: λ≈0
    (lam, _) = equatorial_to_ecliptic(0.0, 0.0)
    sep = angular_separation(parse_ra("06h 45m 08.9s"), parse_dec("-16° 42′ 58″"),
                             parse_ra("05h 55m 10.3s"), parse_dec("+07° 24′ 25″"))
    ok = 0.0 <= g < 24.0 && isfinite(hor.altitude) &&
         abs(mod(rad2deg(lam), 360.0)) < 1e-6 &&
         abs(rad2deg(sep) - 27.1) < 0.5
    Dict{String,Any}("gmst_h" => g, "gmst_ok" => (0.0 <= g < 24.0),
                     "sirius_betelgeuse_deg" => rad2deg(sep),
                     "separation_ok" => abs(rad2deg(sep) - 27.1) < 0.5,
                     "all_ok" => ok)
end

