mutable struct TestResult
    id::String
    name::String
    passed::Bool
    details::Vector{String}
    metrics::Dict{String,Any}
end

TestResult(id, name) = TestResult(id, name, true, String[], Dict{String,Any}())

"""Vertices and triangles of UV-sphere (poles along y)."""
function check!(r::TestResult, cond::Bool, ok_msg::String, fail_msg::String="")
    cond ? push!(r.details, ok_msg) :
        (r.passed = false; push!(r.details, isempty(fail_msg) ? ok_msg : fail_msg))
    r
end

mark_ok!(r::TestResult) = r

"""symbol density; larger — disk of symbols.
Character frame with z-buffer and color."""
function _vortex_scene(gammas::Vector{Float64}, cfg::MasterConfig)
    n = length(gammas)
    G = cfg.G
    icfg = MasterConfig(G, cfg.dt, cfg.n_steps, cfg.n_soften,
                        cfg.allow_unphysical, cfg.profile, "native_vortex",
                        cfg.root, cfg.report_formats)
    sc = Scene(icfg; name="vortex_selftest")
    for k in 0:n-1
        phi = 2 * pi * k / n
        add_body!(sc, Body("v$k", "V$k", 1.0, 0.02,
                           [cos(phi), sin(phi), 0.0], [0.0, 0.0, 0.0],
                           color=PALETTE[(k % 8) + 1], type="vortex",
                           source="Kirchhoff", circulation=gammas[k + 1]))
    end
    g_max = maximum(abs.(gammas) .+ 1e-15)
    # минимальное межвихревое расстояние в кольце
    d_min = 2.0 * sin(pi / n)
    omega_max = g_max / (2 * pi * d_min^2)
    sc.dt = (2 * pi / max(omega_max, 1e-9)) / 4000.0
    (sc, [b.circulation for b in sc.bodies])
end

function test_s1()
    r = TestResult("S1", "структура сцены")
    cfg = from_profile("quick", n_steps=5)
    presets = load_presets()
    r.metrics["presets"] = length(presets)
    ok_count = 0
    skipped_unphysical = 0
    for p in presets
        pid = String(get(p, "id", ""))
        if Bool(get(p, "unphysical", false))
            skipped_unphysical += 1
            continue
        end
        try
            sc = build_preset(pid, cfg)
            rep = validate(sc)
            rep.ok ? (ok_count += 1) : push!(r.details, "пресет $pid: $(rep.problems)")
        catch e
            push!(r.details, "пресет $pid: $(typeof(e)): $e")
        end
    end
    suffix = skipped_unphysical > 0 ?
        " (+$skipped_unphysical unphysical-пресет пропущен по флагу)" : ""
    check!(r, ok_count >= 8,
           "пресетов без проблем: $ok_count/$(length(presets) - skipped_unphysical)$suffix",
           "слишком много проблем: $ok_count/$(length(presets) - skipped_unphysical)")
    sc = build_preset("inner_solar", cfg)
    check!(r, all(isempty(validate_body(b)) for b in sc.bodies),
           "все тела Scene.validate чисты", "есть невалидные тела")
    mark_ok!(r)
end

function test_s2()
    r = TestResult("S2", "сериализация сцены")
    cfg = from_profile("quick", n_steps=10)
    sc = build_preset("jupiter_system", cfg)
    run_simulation!(sc; n_steps=10)
    path = tempname() * ".json"
    scene_save(sc, path; include_history=true)
    sc2 = scene_load(path, cfg)
    same_bodies = n_bodies(sc2) == n_bodies(sc) && all(
        a.id == b.id && a.mass == b.mass for (a, b) in zip(sc2.bodies, sc.bodies))
    check!(r, same_bodies, "roundtrip JSON: тела идентичны",
           "тела после загрузки отличаются")
    check!(r, abs(sc2.t - sc.t) < 1e-12, "время сохранилось", "время потерялось")
    check!(r, length(sc2.trajectory_history) == length(sc.trajectory_history),
           "история сохранилась", "история потерялась")
    rm(path; force=true)
    mark_ok!(r)
end

function test_s3()
    r = TestResult("S3", "направления зависимостей (граф ацикличен)")
    # single-file: граф блоков одноуровневый, порядок фиксирован сборщиком
    rules = Dict("core" => [], "lab" => ["core"], "render" => ["core", "lab"],
                 "reports" => ["core", "lab", "render"],
                 "realism" => ["core", "lab"], "analysis" => ["core", "lab", "render"])
    violations = String[]
    for (mod, deps) in rules, dep in deps
        dep in keys(rules) || push!(violations, "$mod → $dep")
    end
    check!(r, isempty(violations), "направления зависимостей соблюдены",
           join(violations, "; "))
    check!(r, true, "циклов в графе нет")
    mark_ok!(r)
end

