    cfg = from_profile("quick", n_steps=50)
    sc = build_preset("lagrange_triangle", cfg)
    eng = get_engine(sc, "rebound")
    ok_fallback = occursin("fallback", join(sc.events))
    e0 = total_energy(sc)
    run_simulation!(sc; n_steps=50)
    d = norm(sc.bodies[1].position)
    check!(r, ok_fallback, "REBOUND не установлен — fallback в events (штатный)")
