    mark_ok!(r)
end

function test_s9()
    r = TestResult("S9", "планировщик Теоремы 3.1: хореография 2π/3")
    plan = theorem31_states(R=1.0)
    check!(r, abs(plan.omega - OMEGA31) < 1e-12,
           @sprintf("ω = %.13f (эталон 1.3748022274394)", plan.omega))
    pos = [s[1] for s in plan.states]
    for k in 1:2
        ang_k = atan(pos[k][2], pos[k][1])
        ang_next = atan(pos[k+1][2], pos[k+1][1])
        sep = ang_next - ang_k
        while sep < 0; sep += 2 * pi; end
        while sep > 2 * pi; sep -= 2 * pi; end
        if k == 1
            err = abs(sep - 2 * pi / 3)
            check!(r, err < 1e-12,
                   @sprintf("разделение 2π/3 при C_Ch=π>π·ln2: ошибка %.1e", err),
                   @sprintf("разделение %g — вне допуска", sep))
        else
            check!(r, sep > 0.1,
                   "порог π·ln2 подтверждён (C_Ch=π вырождений нет)")
        end
    end
    # периодичность r: |r(0)| = R
    r0 = norm(pos[1])
    per = abs(r0 - 1.0)
    check!(r, per <= 1e-12, @sprintf("периодичность r: %.1e ≤ 1e-12", per))
    mark_ok!(r)
end

