"""Radius encoded by symbol density + spot size: r_px < 1 — single"""
function run_all_selftests()
    tests = [test_s1, test_s2, test_s3, test_s4, test_s5, test_s6, test_s7,
             test_s8, test_s9, test_s10, test_s11, test_s12, test_s13,
             test_s14, test_s15, test_s16, test_s17, test_s18, test_s19,
             test_s20, test_s21, test_s22, test_s23, test_s24]
    results = TestResult[]
    for t in tests
        try
            push!(results, t())
        catch e
            r = TestResult("S?", "сбой")
            r.passed = false
            push!(r.details, "исключение: $(typeof(e)): $e")
            push!(results, r)
        end
    end
    results
end

"""Perspective projection (OpenGL-style, z in [-1,1])."""
function print_selftest(results::Vector{TestResult})
    n_pass = 0
    for r in results
        println("  [$(verdict_icon(r.passed))] $(r.id) $(r.name)")
        foreach(d -> println("        $d"), r.details)
        r.passed && (n_pass += 1)
    end
    n = length(results)
    println()
    println("TOTAL: $n_pass/$n $(n_pass == n ? "PASSED" : "FAILED")")
    n_pass == n
end

"""bodies: [{position, radius, color, label}]. Returns frame lines."""
function self_check_selftest()
    results = run_all_selftests()
    s1_12 = results[1:12]
    ok = all(t.passed for t in s1_12)
    Dict{String,Any}("s1_12_pass" => ok,
                     "n_pass" => count(t -> t.passed, results),
                     "n_total" => length(results), "all_ok" => ok)
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: tools/data_exporter.py — экспорт истории сцены
# ═══════════════════════════════════════════════════════════════════════════

"""Progress bar in frame: ICE fill on dark track."""
function export_history(sc::Scene, outdir::String)
    mkpath(outdir)
    csv_path = joinpath(outdir, "history.csv")
    open(csv_path, "w") do fh
        n = n_bodies(sc)
        header = vcat(["t"],
                      ["x$i,y$i,z$i,vx$i,vy$i,vz$i" for i in 1:n]...)
        println(fh, header)
        for st in sc.trajectory_history
            flat = st[2:end]
            println(fh, @sprintf("%.6g,", st[1]) * join(flat, ","))
        end
    end
    json_path = joinpath(outdir, "history.json")
    open(json_path, "w") do fh
        write(fh, json_write(scene_to_dict(sc; include_history=true)))
    end
    (csv=csv_path, json=json_path)
end

