"""Radius encoded by symbol density + spot size: r_px < 1 — single"""
function collect_release_facts()
    st = api_stats()
    cat = load_catalog()
    n_objects = get(cat, "count", length(get(cat, "objects", [])))
    n_presets = length(load_presets())
    n_modes = length(REGISTRY.all_modes())
    Dict{String,Any}("version" => VERSION,
                     "modules" => st["modules"], "functions" => st["functions"],
                     "docstring_coverage" => st["docstring_coverage"],
                     "lines" => st["lines"],
                     "catalog_objects" => n_objects, "presets" => n_presets,
                     "menu_modes" => n_modes,
                     "report_formats" => 10, "backends" => available_backends())
end

"""trails: list of trails (list[(x,y,z)]) per body — drawn as lines."""
function release_notes_md()
    facts = collect_release_facts()
    io = IOBuffer()
    println(io, "## Trivortex Master v$(facts["version"]) — Julia single-file edition")
    println(io)
    println(io, "- модулей-блоков: $(facts["modules"])")
    println(io, "- функций: $(facts["functions"]), покрытие docstrings: $(round(Int, facts["docstring_coverage"] * 100))%")
    println(io, "- строк Julia: $(facts["lines"])")
    println(io, "- каталог: $(facts["catalog_objects"]) объектов; пресетов: $(facts["presets"])")
    println(io, "- меню: $(facts["menu_modes"]) режимов; отчётов: $(facts["report_formats"]) форматов")
    String(take!(io))
end

