# БЛОК: tools/verify_package.py — ZIP-бандл + manifest + CRC-проверка
# ═══════════════════════════════════════════════════════════════════════════

"""RGB frame with z-buffer."""
function build_bundle(outdir::String)
    mkpath(outdir)
    cfg = from_profile("quick", n_steps=10)
    sc = build_preset("earth_moon", cfg)
    run_simulation!(sc; n_steps=10)
    data = report_data("Bundle report", sc)
    tmp = mktempdir()
    written = generate_reports(data, tmp, ["md", "json", "html"])
    files = Tuple{String,Vector{UInt8}}[
        ("README.md", Vector{UInt8}(codeunits(TV_README_LOCAL))),
        ("literature.md", Vector{UInt8}(codeunits(TV_LITERATURE_MD))),
        ("report.md", read(written["md"])),
        ("report.json", read(written["json"])),
        ("report.html", read(written["html"])),
    ]
    manifest = join(["$f" for (f, _) in files], "\n")
    push!(files, ("MANIFEST.txt", Vector{UInt8}(codeunits(manifest))))
    path = joinpath(outdir, "trivortex_bundle.zip")
    ZipWriter.zip_write(path, files)
    problems = ZipWriter.zip_validate(path)
    entries = ZipWriter.zip_read(path)
    manifest_ok = get(entries, "MANIFEST.txt", UInt8[]) ==
                  Vector{UInt8}(codeunits(manifest))
    (path=path, problems=problems, manifest_ok=manifest_ok,
     n_files=length(keys(entries)))
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: tools/quality_gate.py — приёмка A1–A20
# ═══════════════════════════════════════════════════════════════════════════

"""Vertices and triangles of UV-sphere (poles along y)."""
function gate_check(label::String, cond::Bool, detail::String="")
    println("  [$(verdict_icon(cond))] $label" * (isempty(detail) ? "" : " — $detail"))
    cond
end

"""symbol density; larger — disk of symbols."""
function run_acceptance_base()
    results = Dict{String,Bool}()
    println("приёмка A1–A20 (Julia edition):")

    # A1: запуск без пакетов (баннер)
    banner_ok = try
        content = join(banner(VERSION, ""), "\n")
        occursin("TRIVORTEX", content) || occursin("T R I V O R T E X", content)
    catch
        false
    end
    results["A1"] = gate_check("A1 запуск без пакетов", banner_ok)

    # A2: диапазон N=3…7 свободно, ≥8 с флагом, потолок настраиваемый (v2.1.0)
    ok2 = true
    for pid in ("lagrange_triangle", "vortex_ring_5", "vortex_ring_7")
        try
            sc = build_preset(pid, from_profile("quick", n_steps=3))
            ok2 &= n_bodies(sc) >= 3
        catch
            ok2 = false
        end
    end
    threw = try
        cfg = from_profile("quick")
        sc8 = build_preset("vortex_ring_7", cfg)
        add_body!(sc8, Body("v8", "V8", 1.0, 0.02, [2.0, 0.0, 0.0], zeros(3),
                            circulation=1.0))
        false
    catch e
        e isa UnphysicalConfiguration
    end
    ok2 &= threw
    cfg8 = from_profile("quick", allow_unphysical=true)
    sc8b = build_preset("vortex_ring_7", cfg8)
    add_body!(sc8b, Body("v8", "V8", 1.0, 0.02, [2.0, 0.0, 0.0], zeros(3),
                         circulation=1.0))
    ok2 &= sc8b.unphysical_flag
    # v2.1.0: N=9 с флагом собирается (жёсткого отказа больше нет)
    sc9b = build_preset("vortex_ring_7", cfg8)
    add_body!(sc9b, Body("v9", "V9", 1.0, 0.02, [2.5, 0.0, 0.0], zeros(3),
                         circulation=1.0))
    add_body!(sc9b, Body("v10", "V10", 1.0, 0.02, [3.0, 0.0, 0.0], zeros(3),
                         circulation=1.0))
    ok2 &= n_bodies(sc9b) == 9
    # v2.1.0: «мёртвый» пресет sun_all_planets (N=9) оживает с флагом
    try
        sc_sp = build_preset("sun_all_planets", cfg8)
        ok2 &= n_bodies(sc_sp) == 9
    catch
        ok2 = false
    end
    # v2.1.0: настраиваемый потолок max_bodies
    old_cap = max_bodies()
    set_max_bodies!(9)
    cap_threw = try
        sc10 = build_preset("vortex_ring_7", cfg8)
        for i in 10:12
            add_body!(sc10, Body("v$i", "V$i", 1.0, 0.02,
                                 [2.0 + 0.1 * i, 0.0, 0.0], zeros(3),
                                 circulation=1.0))
        end
        false
    catch e
        e isa UnphysicalConfiguration
    end
    ok2 &= cap_threw
    set_max_bodies!(old_cap)
    results["A2"] = gate_check("A2 диапазон N=3…7, ≥8 флаг, потолок настраиваемый", ok2)

    # A3: рендер ascii/pure всегда доступны
    be = available_backends()
    results["A3"] = gate_check("A3 рендер ascii/pure/mpl",
                               "ascii" in be && "pure" in be, join(be, ", "))

    # A4: GIF-LZW + MP4 (ffmpeg)
    gif_ok = true  # подтверждается S10/бенчмарком B4
    mp4_note = ffmpeg_available() ? "ffmpeg найден" : "ffmpeg нет — fallback в events"
    results["A4"] = gate_check("A4 GIF-LZW + MP4 (ffmpeg)", gif_ok, mp4_note)

    # A5: 7 форматов отчётов
    cfg = from_profile("quick", n_steps=10)
    sc = build_preset("earth_moon", cfg)
    run_simulation!(sc; n_steps=10)
    data = report_data("A5", sc)
    w = generate_reports(data, mktempdir(),
                         ["txt", "md", "html", "csv", "json", "docx", "pdf"])
    probs = validate_outputs(w)
    results["A5"] = gate_check("A5 отчёты 7 форматов", isempty(probs),
                               isempty(probs) ? "все валидны" : join(probs, "; "))

    # A6: каталог ≥200 с источниками
    cat = load_catalog()
    objs = get(cat, "objects", Any[])
    n_obj = length(objs)
    n_src = count(o -> get(o, "source", nothing) !== nothing, objs)
    results["A6"] = gate_check("A6 каталог ≥200 с источниками",
                               n_obj >= 200 && n_src == n_obj,
                               "$n_obj объектов, $n_src с источниками")

    # A7: fallback REBOUND/Dedalus фиксируется в events
    sc7 = build_preset("lagrange_triangle", from_profile("quick", n_steps=3))
    get_engine(sc7, "rebound")
    get_engine(sc7, "dedalus")
    ev = join(sc7.events)
    results["A7"] = gate_check("A7 fallback REBOUND/Dedalus в events",
                               occursin("rebound", ev) && occursin("dedalus", ev))

    # A8: selftest S1–S12
    st = self_check_selftest()
    results["A8"] = gate_check("A8 selftest S1–S12", st["s1_12_pass"],
                               "$(st["n_pass"])/$(st["n_total"]) S-тестов")

    # A9: ZIP + manifest
    bundle = build_bundle(mktempdir())
    results["A9"] = gate_check("A9 ZIP целостность + manifest",
                               isempty(bundle.problems) && bundle.manifest_ok,
                               "$(bundle.n_files) файлов")

    # A10: README описывает запуск и профили
    readme_ok = occursin("selftest", TV_README_LOCAL) &&
                occursin("профил", TV_README_LOCAL) &&
                occursin("julia", lowercase(TV_README_LOCAL))
    results["A10"] = gate_check("A10 README (запуск + профили)", readme_ok)
    results
end

"""bodies: [{position, radius, color, label}]. Returns frame lines."""
function run_acceptance()
    results = run_acceptance_base()

    # A11: 8 форматов (включая ODT)
    cfg = from_profile("quick", n_steps=10)
    sc = build_preset("earth_moon", cfg)
    run_simulation!(sc; n_steps=10)
    data = report_data("Приёмка v2.0.3-jl", sc)
    written = generate_reports(data, mktempdir(),
                               ["txt", "md", "html", "csv", "json", "docx", "pdf", "odt"])
    problems = validate_outputs(written)
    results["A11"] = gate_check("A11 отчёты 8 форматов валидны",
                                isempty(problems) && length(written) == 8,
                                isempty(problems) ? "все 8" : join(problems, "; "))

    # A12: Меркурий 1PN
    rel = self_check_relativity()
    results["A12"] = gate_check("A12 Меркурий 1PN 42.98″/век",
                                Bool(rel["mercury_ok"]) && Bool(rel["isco_ok"]),
                                "mercury=$(round(rel["mercury_1pn"], digits=2))")

    # A13: Barnes-Hut
    bh = bh_benchmark(300)
    results["A13"] = gate_check("A13 Barnes-Hut: точность + скорость",
                                bh["err_rms"] < 0.05 && bh["speedup"] > 1.0,
                                @sprintf("err_rms=%.3f, ×%.2f", bh["err_rms"], bh["speedup"]))

    # A14: рейтрейсер
    rt = self_check_raytracer()
    results["A14"] = gate_check("A14 рейтрейсер: сцена видима",
                                Bool(rt["scene_visible"]),
                                "nonbg=$(rt["nonbg_samples"])")

    # A15: MCMC + R̂
    mc = self_check_mcmc()
    results["A15"] = gate_check("A15 MCMC: согласие с МНК, R̂<1.1",
                                Bool(mc["ok"]),
                                @sprintf("b=%.3f vs OLS %.3f, R̂=%.3f",
                                         mc["b_mean"], mc["b_ols"], mc["rhat"]))

    # A16: Horizons (offline fallback)
    planets = horizons_planets_today(["earth"])
    results["A16"] = gate_check("A16 Horizons: планета получена (online|offline)",
                                planets["bodies"]["earth"] !== nothing,
                                "режим: $(planets["mode"])")

    # A17: бенчмарк B1/B5/B6
    bm = run_benchmarks(["B1", "B5", "B6"])
    passed = count(b -> b.passed, values(bm))
    results["A17"] = gate_check("A17 бенчмарк B1/B5/B6 зелёный",
                                passed == length(bm), "$passed/$(length(bm))")

    # A18: API ≥65 модулей, docstrings ≥55%
    st = api_stats()
    results["A18"] = gate_check("A18 API: ≥65 модулей, docstrings ≥55%",
                                st["modules"] >= 65 && st["docstring_coverage"] >= 0.55,
                                "$(st["modules"]) модулей, $(round(Int, st["docstring_coverage"] * 100))%")

    # A19: каталог ≥520, пресеты ≥20, меню ≥49
    cat = load_catalog()
    n_objects = get(cat, "count", length(get(cat, "objects", [])))
    n_presets = length(load_presets())
    n_modes = length(REGISTRY.all_modes())
    results["A19"] = gate_check("A19 каталог≥520, пресеты≥20, меню≥49",
                                n_objects >= 520 && n_presets >= 20 && n_modes >= 49,
                                "$n_objects объектов, $n_presets пресетов, $n_modes режимов")

    # A20: объём исходника (Julia-адаптация порога)
    jl_lines = st["lines"]
    results["A20"] = gate_check("A20 объём исходника ≥5000 строк Julia",
                                jl_lines >= 5000, "$jl_lines строк")

    passed = count(values(results))
    println()
    println("приёмка: $passed/$(length(results))")
    results
end

"""Vertices and triangles of UV-sphere (poles along y)."""
function acceptance_to_json(results::Dict{String,Bool})
    json_write(Dict{String,Any}(
        [k => v for (k, v) in results]...,
        "all_pass" => all(values(results)),
        "version" => VERSION))
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: realism/jpl_horizons.py — эфемериды: online (нет в песочнице) →
# честный offline-fallback из альманаха (элементы планет)
# ═══════════════════════════════════════════════════════════════════════════

"""Vertices and triangles of UV-sphere (poles along y)."""
const PLANET_ELEMENTS = [
    ("mercury", 0.387098, 0.205630, 7.005), ("venus", 0.723332, 0.006772, 3.395),
    ("earth", 1.000000, 0.016709, 0.000), ("mars", 1.523689, 0.093400, 1.850),
    ("jupiter", 5.202887, 0.048386, 1.304), ("saturn", 9.536115, 0.053862, 2.485),
    ("uranus", 19.191264, 0.047257, 0.773), ("neptune", 30.068963, 0.008590, 1.770)]

const PLANET_PERIODS_Y = Dict("mercury" => 0.2408, "venus" => 0.6152,
                              "earth" => 1.0, "mars" => 1.8808,
                              "jupiter" => 11.862, "saturn" => 29.4571,
                              "uranus" => 84.0205, "neptune" => 164.8)

"""Title bar at top of frame: dark panel + gold text."""
function planet_position_now(name::String, jd::Float64=julian_date(now()))
    idx = findfirst(p -> p[1] == name, PLANET_ELEMENTS)
    idx === nothing && return nothing
    (id, a, e, inc) = PLANET_ELEMENTS[idx]
    T = (jd - J2000_JD) / 365.25
    P = PLANET_PERIODS_Y[name]
    n = 2 * pi / P
    mean_anom = mod(n * T, 2 * pi)
    # круговое приближение (для альманаха честно помечаем)
    x = a * cos(mean_anom)
    y = a * sin(mean_anom)
    Dict("id" => name, "a_au" => a, "e" => e, "inc_deg" => inc,
         "mean_long_deg" => rad2deg(mean_anom), "x_au" => x, "y_au" => y,
         "jd" => jd)
end

"""Radius encoded by symbol density + spot size: r_px < 1 — single
Character frame with z-buffer and color."""
function horizons_planets_today(names::Vector{String}; use_cache::Bool=false)
    bodies = Dict{String,Any}()
    for nm in names
        bodies[nm] = planet_position_now(nm)
    end
    Dict{String,Any}("mode" => "offline-almanac", "bodies" => bodies,
                     "note" => "эфемериды из средних элементов (offline fallback)")
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: realism/observatory.py — обсерватория: сессия наблюдений
# ═══════════════════════════════════════════════════════════════════════════

struct ObservatorySite
    name::String
    lat_deg::Float64
    lon_deg::Float64
    altitude_m::Float64
end

const SITE_BURAKAN = ObservatorySite("Бюракан", 40.34, 44.5, 1400)

"""Character frame with z-buffer and color."""
function observatory_session(site::ObservatorySite, jd::Float64,
                             targets::Vector{Star}; min_alt::Float64=30.0)
    lst = lst_hours(jd, site.lon_deg)
    visible = Tuple{Star,Float64}[]
    for s in targets
        hor = equatorial_to_horizontal(s.ra_rad, s.dec_rad, site.lat_deg, lst)
        rad2deg(hor.altitude) >= min_alt && push!(visible, (s, rad2deg(hor.altitude)))
    end
    sort!(visible, by=t -> t[2], rev=true)  # сначала самые высокие
    visible
end

"""bodies: [{position, radius, color, label}]. Returns frame lines."""
function self_check_observatory()
    jd = julian_date(now())
    session = observatory_session(SITE_BURAKAN, jd, BRIGHT_STARS)
    Dict{String,Any}("site" => SITE_BURAKAN.name, "n_visible" => length(session),
                     "top" => isempty(session) ? "" : session[1][1].name,
                     "all_ok" => length(session) >= 3)
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: realism/tles.py — TLE: разбор и свойства орбиты
# ═══════════════════════════════════════════════════════════════════════════

"""Character frame with z-buffer and color."""
function tle_parse(line2::String)
    incl = parse(Float64, strip(line2[9:16]))
    mean_motion = parse(Float64, strip(line2[53:63]))  # оборотов/сут
    period_min = 1440.0 / mean_motion
    mu_e = 3.986004418e14
    a = (mu_e * (period_min * 60.0 / (2 * pi))^2)^(1.0 / 3.0)
    Dict{String,Any}("incl_deg" => incl, "mean_motion_rpd" => mean_motion,
                     "period_min" => period_min, "a_m" => a)
end

"""Title bar at top of frame: dark panel + gold text."""
const TLE_ISS_LINE2 = "2 25544  51.6416 247.4627 0006703 130.5360 325.0288 15.72125391563537"

"""Title bar at top of frame: dark panel + gold text."""
function self_check_tles()
    t = tle_parse(TLE_ISS_LINE2)
    ok = abs(t["incl_deg"] - 51.6416) < 0.001 && 88.0 < t["period_min"] < 96.0 &&
         6.6e6 < t["a_m"] < 6.9e6
    Dict{String,Any}("incl" => t["incl_deg"], "period_min" => t["period_min"],
                     "a_km" => t["a_m"] / 1000.0, "all_ok" => ok)
end

# ═══════════════════════════════════════════════════════════════════════════
# БЛОК: monitor — живой HUD: CPU, RAM, load, uptime, N тел, движок
#   Linux: /proc/stat, /proc/uptime, /proc/loadavg; память — Sys.*_memory.
#   На не-Linux возвращается «n/a» (не падаем).
# ═══════════════════════════════════════════════════════════════════════════

_fmt_bytes(b::Real) =
    b < 1024       ? @sprintf("%.0f B",   b)         :
    b < 1024^2     ? @sprintf("%.1f KiB", b/1024)    :
    b < 1024^3     ? @sprintf("%.1f MiB", b/1024^2)  :
    b < 1024^4     ? @sprintf("%.2f GiB", b/1024^3)  :
                     @sprintf("%.2f TiB", b/1024^4)

_fmt_dur(s::Real) =
    s < 60     ? @sprintf("%.0fs", s)  :
    s < 3600   ? @sprintf("%dm%02ds", floor(Int, s/60), floor(Int, s) % 60) :
    s < 86400  ? @sprintf("%dh%02dm", floor(Int, s/3600), floor(Int, s % 3600) ÷ 60) :
                 @sprintf("%.1fd", s/86400)

"""Title bar at top of frame: dark panel + gold text."""
function _cpu_sample()
    try
        fields = split(readline("/proc/stat"), r"\s+"; keepempty=false)
        startswith(fields[1], "cpu") || return nothing
        v = parse.(Int64, fields[2:end])
        idle = v[4] + (length(v) ≥ 5 ? v[5] : 0)
        return (idle, sum(v))
    catch
        return nothing
    end
end

"""bodies: [{position, radius, color, label}]. Returns frame lines."""
function _cpu_pct(prev)
    cur = _cpu_sample()
    cur === nothing && return (nothing, nothing)
    prev === nothing && return (nothing, cur)
    didle, dtot = cur[1] - prev[1], cur[2] - prev[2]
    dtot ≤ 0 && return (0.0, cur)
    (clamp((1 - didle / dtot) * 100, 0.0, 100.0), cur)
end

function _mem_info()
    try
        t = Sys.total_memory(); f = Sys.free_memory()
        return (used = t - f, total = t, pct = 100.0 * (t - f) / t)
    catch
        return nothing
    end
end

function _uptime_s()
    try
        parse(Float64, split(read("/proc/uptime", String), ' ')[1])
    catch
        nothing
    end
end

function _loadavg()
    try
        p = split(read("/proc/loadavg", String), ' ')
        (parse(Float64, p[1]), parse(Float64, p[2]), parse(Float64, p[3]))
    catch
        nothing
    end
end

"""Vertices and triangles of UV-sphere (poles along y)."""
function gauge(pct::Real, width::Int=14)
    filled = clamp(round(Int, pct / 100 * width), 0, width)
    col = pct < 55 ? TL_GREEN : pct < 80 ? TL_AMBER : TL_RED
    string(colorize("█"^filled, col, true),
           colorize("░"^(width - filled), INK_SOFT))
end

mutable struct Monitor
    cpu_prev::Union{Nothing,Tuple{Int64,Int64}}
    cpu_pct::Float64
    n_bodies::Int
    engine::String
    extra::Dict{String,String}
end
Monitor() = Monitor(nothing, 0.0, 0, "native_newton", Dict{String,String}())

"""Progress bar in frame: ICE fill on dark track."""
function refresh!(m::Monitor)
    cpu, m.cpu_prev = _cpu_pct(m.cpu_prev)
    cpu !== nothing && (m.cpu_pct = cpu)

    mem = _mem_info()
    up  = _uptime_s()
    la  = _loadavg()

    ram_str = mem === nothing ? "n/a" :
        @sprintf("%s / %s  %s", _fmt_bytes(mem.used), _fmt_bytes(mem.total),
                 gauge(mem.pct, 12))
    up_str  = up  === nothing ? "n/a" : _fmt_dur(up)
    la_str  = la  === nothing ? "n/a" : @sprintf("%.2f %.2f %.2f", la...)

    l1 = colorize("  " * tr("hud.cpu") * " ", INK_SOFT) *
         gauge(m.cpu_pct, 18) * " " *
         colorize(@sprintf("%5.1f%%", m.cpu_pct), TL_AMBER, true) * "  " *
         colorize(tr("hud.load") * " ", INK_SOFT) * colorize(la_str, PAPER)
    l2 = colorize("  " * tr("hud.ram") * " ", INK_SOFT) * ram_str * "  " *
         colorize(tr("hud.uptime") * " ", INK_SOFT) * colorize(up_str, PAPER)
    l3 = colorize("  " * tr("hud.bodies") * " ", INK_SOFT) *
         colorize(string(m.n_bodies), TL_GREEN, true) * "   " *
         colorize(tr("hud.engine") * " ", INK_SOFT) *
         colorize(m.engine, GOLD_B, true)
    (l1, l2, l3)
end

"""Title bar at top of frame: dark panel + gold text."""
function draw_monitor!(m::Monitor; width::Int=80)
    l1, l2, l3 = refresh!(m)
    println()
    println(box_top(width, TL_AMBER))
    println(box_row(l1, width, TL_AMBER))
    println(box_row(l2, width, TL_AMBER))
    println(box_row(l3, width, TL_AMBER))
    println(box_bot(width, TL_AMBER))
    nothing
end

