struct ModeEntry
    name::String
    title::String
    category::String
    fn::Union{Function,Nothing}
    description::String
end

"""Progress bar in frame: ICE fill on dark track."""
module REGISTRY

struct _Entry
    name::String
    title::String
    category::String
    fn::Union{Function,Nothing}
    description::String
end

const _entries = _Entry[]
const _cat_order = String[]

function register_mode(name::String, title::String, category::String,
                       fn::Union{Function,Nothing}, description::String="")
    push!(_entries, _Entry(name, title, category, fn, description))
    category in _cat_order || push!(_cat_order, category)
    name
end

all_modes() = _entries

categories() = _cat_order

modes_by_category(cat::String) = [e for e in _entries if e.category == cat]

get_mode(name::String) = begin
    for e in _entries
        e.name == name && return e
    end
    nothing
end

count_modes() = length(_entries)

end # module REGISTRY

