"""trails: list of trails (list[(x,y,z)]) per body — drawn as lines."""
mutable struct App
    config::MasterConfig
    scene::Union{Scene,Nothing}
    last_sim::Union{Scene,Nothing}
    last_reports::Dict{String,String}
    runs_dir::String
    session_log::String
end

App() = begin
    cfg = from_profile("standard")
    runs = joinpath(ROOT, "runs")
    mkpath(runs)
    App(cfg, nothing, nothing, Dict{String,String}(), runs,
        joinpath(runs, "session_jl.log"))
end

const APP_REF = Ref{Union{App,Nothing}}(nothing)

"""trails: list of trails (list[(x,y,z)]) per body — drawn as lines."""
app() = begin
    if APP_REF[] === nothing
        APP_REF[] = App()
    end
    APP_REF[]
end

app_log(app::App, msg::String) = begin
    try
        open(app.session_log, "a") do fh
            println(fh, "$(Dates.format(now(), "yyyy-mm-ddTHH:MM:SS"))  $msg")
        end
    catch
    end
end

"""Progress bar in frame: ICE fill on dark track."""
function require_scene(app::App)
    if app.scene === nothing
        println(colorize("\n  ⚠ " * tr("err.noscene"), ORG))
        return nothing
    end
    app.scene
end

_run_selfcheck_mode(label::String, subtitle::String, f::Function) = begin
    println(colorize("\n  $label", CYN, true))
    println("  $subtitle")
    res = Dict{String,Any}()
    ok = false
    try
        res = f()
        ok = Bool(get(res, "all_ok", get(res, "ok", false)))
    catch e
        res = Dict{String,Any}("error" => "$(typeof(e)): $e")
        ok = false
    end
    println("  $(verdict_icon(ok)) " * (ok ? "проверка пройдена" :
            "ПРОВАЛ: $(get(res, "error", "несоответствие эталону"))"))
    shown = 0
    for (k, v) in res
        shown >= 6 && break
        k == "error" && continue
        (v isa Real || v isa Bool || v isa String) || continue
        if v isa Real && (abs(v) < 1e-3 || abs(v) > 1e6)
            println(kv(String(k), @sprintf("%.3e", v)))
        else
            println(kv(String(k), string(v)))
        end
        shown += 1
    end
    res
end

_scene_var_str(v) = v isa Real ? @sprintf("%.6g", v) : string(v)

# ── v2.1.0: ввод с значением по умолчанию (Enter = текущее, EOF = текущее) ──

"""Title bar at top of frame: dark panel + gold text."""
function _ask_f(label::String, cur::Real; lo::Real=-Inf)
    while true
        print("  $label [$cur] > ")
        s = strip(readline())
        isempty(s) && return Float64(cur)
        v = tryparse(Float64, s)
        if v === nothing
            println("  не число — повторите (или Enter для $cur)")
        elseif v < lo
            println("  значение должно быть ≥ $lo — повторите")
        else
            return v
        end
    end
end

"""Progress bar in frame: ICE fill on dark track."""
function _ask_i(label::String, cur::Integer; lo::Int=typemin(Int))
    while true
        print("  $label [$cur] > ")
        s = strip(readline())
        isempty(s) && return Int(cur)
        v = tryparse(Int, s)
        if v === nothing
            println("  не целое — повторите (или Enter для $cur)")
        elseif v < lo
            println("  значение должно быть ≥ $lo — повторите")
        else
            return v
        end
    end
end

"""Perspective projection (OpenGL-style, z in [-1,1])."""
function _ask_choice(label::String, options::Vector{Tuple{String,String}},
                     default::String)
    println("  $label:")
    for (i, (k, descr)) in enumerate(options)
        d = k == default ? "  ← по умолчанию" : ""
        println("    [$(i)] $(rpad(k, 13)) $(descr)$(d)")
    end
    print("  выбор [1-$(length(options)), Enter=$(default)] > ")
    s = String(strip(readline()))
    isempty(s) && return default
    i = tryparse(Int, s)
    if i !== nothing && 1 <= i <= length(options)
        return options[i][1]
    end
    s in first.(options) && return s
    default
end

