    # Анализ (17)
    R("analysis_selftest", "Структурные тесты S1–S24", "Анализ",
      () -> begin
          results = run_all_selftests()
          print_selftest(results)
      end, "полный selftest")
    R("analysis_lombscargle", "Ломб-Скаргл", "Анализ",
      () -> begin
          rng = MersenneTwister(1)
          t = collect(0.1:0.15:60.0)
          y = [sin(2 * pi * ti / 4.0) + randn(rng) * 0.3 for ti in t]
          dy = fill(0.3, length(t))
          res = ls_best_period(t, y, dy)
          println(kv("период", @sprintf("%.3f (истина 4.0)", res.period)))
          println(kv("мощность", @sprintf("%.4f", res.power)))
          println(kv("FAP", @sprintf("%.2e", res.fap)))
          res
      end, "периодограмма")
    R("analysis_ttvs", "TTV-анализ", "Анализ",
      () -> begin
          rng = MersenneTwister(2)
          P = 5.0
          epochs = collect(0.0:14.0)
          ttv = [0.02 * sin(2 * pi * e * P / 40.0) for e in epochs]
          t_obs = [e * P + ttv[i] + randn(rng) * 0.002 for (i, e) in enumerate(epochs)]
          res = oc_residuals(epochs, t_obs)
          amp = ttv_amplitude(epochs, t_obs)
          println(kv("P", @sprintf("%.4f сут", res.eph.P)))
          println(kv("T0", @sprintf("%.4f", res.eph.T0)))
          println(kv("амплитуда O−C", @sprintf("%.4f сут", amp.amplitude)))
          res
      end, "O−C")
    R("analysis_bls", "BLS транзиты", "Анализ",
      () -> begin
          rng = MersenneTwister(3)
          P_true = 10.0
          t = collect(0.0:0.02:80.0)
          y = Float64[]
          for ti in t
              ph = mod(ti, P_true)
              v = 1.0 - ((0.4 < ph < 0.5) ? 0.01 : 0.0) + randn(rng) * 0.001
              push!(y, v)
          end
          periods = collect(range(5.0, 20.0; length=60))
          res = box_least_squares(t, y, periods)
          println(kv("период", @sprintf("%.3f (истина %.1f)", res.period, P_true)))
          println(kv("глубина", @sprintf("%.4f", res.depth)))
          res
      end, "box least squares")
    R("analysis_mcmc", "MCMC Метрополиса", "Анализ",
      () -> _run_selfcheck_mode("analysis_mcmc", "R̂ Гельмана-Рубина, согласие с МНК",
